package sprint

import (
	"context"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	pprocess "github.com/Antonio7098/ultraplan-go/internal/platform/process"
)

type performanceOptimizationResult struct {
	Changed             bool
	Stalled             bool
	FinalImplementation string
}

func (s Service) optimizePerformance(ctx context.Context, prepared PerformancePrepareResult, manifest PerformanceBenchmarkManifest, baseline []PerformanceMeasurement, store PerformanceStore, state *PerformanceState, token VerificationWriterToken, env []string) (performanceOptimizationResult, error) {
	identity, err := targetIdentity(prepared.Target.Path)
	if err != nil {
		return performanceOptimizationResult{}, err
	}
	out := performanceOptimizationResult{FinalImplementation: identity}
	if s.runtime == nil {
		return out, nil
	}
	descriptors := map[string]PerformanceDescriptor{}
	for _, descriptor := range manifest.Descriptors {
		for _, id := range descriptor.TargetIDs {
			descriptors[id] = descriptor
		}
	}
	current := make(map[string]PerformanceMeasurement, len(baseline))
	for _, measurement := range baseline {
		current[measurement.Target.ID] = measurement
	}
	baseRunner := s.processRunner
	if baseRunner == nil {
		baseRunner = pprocess.DirectRunner{}
	}
	for state.Counters.OptimizationCycles < state.Limits.OptimizationCycles {
		comparisons := make([]PerformanceComparison, 0, len(prepared.Packet.Targets))
		for _, target := range prepared.Packet.Targets {
			value := current[target.ID]
			comparison, compareErr := ComparePerformanceTarget(target, baselineMeasurement(baseline, target.ID).Qualification.Median, value.Qualification.Median, value.Qualification.Qualified, false)
			if compareErr != nil {
				return out, compareErr
			}
			comparisons = append(comparisons, comparison)
		}
		selected, ok := SelectPerformanceMiss(prepared.Packet.Targets, comparisons)
		if !ok {
			return out, nil
		}
		neededCommands := 1 + len(prepared.CorrectnessCommands) + state.Limits.Warmups + selected.Samples
		for _, result := range performanceAlreadyMet(prepared.Packet.Targets, comparisons, current) {
			neededCommands += state.Limits.Warmups + result.Target.Samples
		}
		// A cycle may start only when the complete final measurement and
		// correctness boundary still fits afterward.
		neededCommands += len(prepared.CorrectnessCommands)
		for _, target := range prepared.Packet.Targets {
			neededCommands += state.Limits.Warmups + target.Samples
		}
		if state.Counters.Commands+neededCommands > state.Limits.Commands {
			state.Counters.OptimizationCycles = state.Limits.OptimizationCycles
			state.NextAction = "Command budget exhausted; finalize without another optimization proposal."
			state.UpdatedAt = s.now().UTC()
			out.Stalled = true
			if _, err := store.PublishState(*state, token); err != nil {
				return out, err
			}
			return out, nil
		}
		cycle := state.Counters.OptimizationCycles + 1
		state.Counters.OptimizationCycles, state.Phase, state.NextAction, state.UpdatedAt = cycle, PerformancePhaseOptimizing, "Evaluate one isolated proposal for "+selected.ID+".", s.now().UTC()
		if _, err := store.PublishState(*state, token); err != nil {
			return out, err
		}
		isolation, err := createPerformanceIsolation(ctx, prepared.Target.Path, prepared.ProtectedRoots, state.Limits)
		if err != nil {
			return out, err
		}
		profileKind, err := PerformanceProfileForUnit(descriptors[selected.ID].RawUnit)
		if err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		profileOutput := filepath.Join(isolation.parent, fmt.Sprintf("profile-%06d.pprof", cycle))
		profileRequest, err := PerformanceProfileRequest(isolation.workspace.Path, profileOutput, descriptors[selected.ID], profileKind, state.Limits, env)
		if err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		state.Counters.Commands++
		profileResult, profileErr := isolation.runner(baseRunner).Run(ctx, profileRequest)
		if profileErr != nil || !profileResult.CleanupComplete || profileResult.StdoutTruncated || profileResult.StderrTruncated {
			cleanupErr := isolation.cleanup()
			return out, errors.Join(fmt.Errorf("performance profile command failed: %w", profileErr), cleanupErr)
		}
		profileBytes := []byte(profileResult.Stdout)
		if info, statErr := os.Lstat(profileOutput); statErr == nil {
			if !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 || info.Size() > int64(state.Limits.ProfileBytes) {
				_ = isolation.cleanup()
				return out, fmt.Errorf("performance profile output is unsafe or exceeds its retained-byte limit")
			}
			if retained, readErr := os.ReadFile(profileOutput); readErr == nil {
				profileBytes = retained
			} else {
				_ = isolation.cleanup()
				return out, readErr
			}
		} else if !errors.Is(statErr, fs.ErrNotExist) {
			_ = isolation.cleanup()
			return out, statErr
		}
		if removeErr := os.Remove(profileOutput); removeErr != nil && !errors.Is(removeErr, fs.ErrNotExist) {
			_ = isolation.cleanup()
			return out, removeErr
		}
		if len(profileBytes) == 0 {
			profileBytes = []byte("profile command completed without retained output\n")
		}
		if len(profileBytes) > state.Limits.ProfileBytes {
			_ = isolation.cleanup()
			return out, fmt.Errorf("performance profile exceeds retained-byte limit")
		}
		profileDataPath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "profile.pprof")
		profileDataRef, err := store.PublishBytes(profileDataPath, "cycle-profile-data", profileBytes, true, token)
		if err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		profile := PerformanceProfile{SchemaVersion: PerformanceSchemaVersion, Cycle: cycle, TargetID: selected.ID, Kind: profileKind, Implementation: identity, Digest: profileDataRef.Digest, Bytes: len(profileBytes), Artifact: profileDataRef}
		profilePath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "profile.json")
		if _, err := store.PublishJSON(profilePath, "cycle-profile", profile, true, token); err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		state.Counters.RuntimeAttempts++
		if _, err := store.PublishState(*state, token); err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		prompt := performanceOptimizationPrompt(selected, profile)
		request := s.runtimeRequest(prompt, map[string]string{"project": prepared.Project, "sprint": prepared.Sprint, "stage": string(VerificationPhasePerformance), "operation": "performance-optimization", "cycle": fmt.Sprint(cycle), "target": selected.ID})
		if override, ok := s.verificationRuntime[VerificationPhasePerformance]; ok {
			request.Provider, request.Model = splitProviderModel(override.Model)
			request.Metadata["variant"] = override.Variant
		}
		request.WorkDir, request.Timeout, request.Sandbox, request.Permissions = isolation.workspace.Path, state.Limits.WallTime, "workspace_write", "restricted"
		request.Policy.Default = "deny"
		request.Policy.Tools = map[string]string{"read": "allow", "list": "allow", "search": "allow", "glob": "allow", "write": "allow", "edit": "allow", "patch": "allow", "bash": "deny", "shell": "deny"}
		runtimeResult, runErr := s.runtime.StartRun(ctx, request)
		if cleanupErr := s.deleteCompletedSessions(context.WithoutCancel(ctx), runtimeResult); cleanupErr != nil {
			runErr = errors.Join(runErr, cleanupErr)
		}
		if runErr != nil {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, fmt.Errorf("runtime proposal failed: %w", runErr))
			_ = isolation.cleanup()
			if ctx.Err() != nil {
				return out, ctx.Err()
			}
			if state.Counters.RuntimeAttempts >= state.Limits.OptimizationCycles*state.Limits.OptimizationAttempts {
				out.Stalled = true
				return out, nil
			}
			continue
		}
		changed, diffErr := pprocess.CompareTrees(context.WithoutCancel(ctx), prepared.Target.Path, isolation.workspace.Path, pprocess.IsolationLimits{MaxFiles: performanceIsolationFiles, MaxBytes: performanceIsolationBytes, MaxFileSize: performanceIsolationFileSize, Timeout: state.Limits.CommandTimeout})
		replacements, preimages, changedBytes, deriveErr := derivePerformanceProductionProposal(prepared.Target.Path, isolation.workspace.Path, changed, state.Limits)
		if diffErr != nil || deriveErr != nil {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, errors.Join(diffErr, deriveErr))
			_ = isolation.cleanup()
			continue
		}
		patch := []byte(renderPerformancePatch(prepared.Target.Path, isolation.workspace.Path, changed))
		if len(patch) == 0 || len(patch) > state.Limits.ProposalBytes {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, fmt.Errorf("proposal patch exceeds retained-byte limit"))
			_ = isolation.cleanup()
			continue
		}
		proposalPath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "proposal.patch")
		if _, err := store.PublishBytes(proposalPath, "cycle-proposal", patch, true, token); err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		hypothesis := PerformanceHypothesis{SchemaVersion: PerformanceSchemaVersion, Cycle: cycle, TargetID: selected.ID, Summary: boundRepairText(runtimeResult.TerminalOutput, 512), ProfileDigest: profile.Digest}
		if hypothesis.Summary == "" {
			hypothesis.Summary = "Runtime proposed one target-linked production change."
		}
		hypothesisPath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "hypothesis.json")
		if _, err := store.PublishJSON(hypothesisPath, "cycle-hypothesis", hypothesis, true, token); err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		scope := PerformanceProposalScope{SchemaVersion: PerformanceSchemaVersion, Cycle: cycle, TargetID: selected.ID, Before: identity, Paths: changed, ChangedBytes: changedBytes, Allowed: true}
		candidateIdentity, identityErr := targetIdentity(isolation.workspace.Path)
		if identityErr != nil {
			_ = isolation.cleanup()
			return out, identityErr
		}
		scope.Candidate = candidateIdentity
		scopePath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "scope.json")
		if _, err := store.PublishJSON(scopePath, "cycle-scope", scope, true, token); err != nil {
			_ = isolation.cleanup()
			return out, err
		}
		if err := runPerformanceCorrectness(ctx, isolation.runner(baseRunner), isolation.workspace.Path, prepared.CorrectnessCommands, state.Limits, env, &state.Counters); err != nil {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, fmt.Errorf("candidate correctness failed: %w", err))
			_ = isolation.cleanup()
			continue
		}
		candidateRunner := &performanceMeasurementAccountingRunner{delegate: isolation.runner(baseRunner), counters: &state.Counters, limits: state.Limits}
		candidate, err := MeasurePerformanceTarget(ctx, candidateRunner, isolation.workspace.Path, descriptors[selected.ID], selected, state.Limits, env, prepared.Packet.PacketDigest, manifest.BenchmarkDigest, currentPerformanceEnvironment(env).Identity)
		if _, publishErr := store.PublishState(*state, token); publishErr != nil {
			_ = isolation.cleanup()
			return out, publishErr
		}
		if err != nil {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, err)
			_ = isolation.cleanup()
			continue
		}
		alreadyMet := performanceAlreadyMet(prepared.Packet.Targets, comparisons, current)
		remeasurements := make(map[string]PerformanceMeasurement, len(alreadyMet))
		for i := range alreadyMet {
			target := alreadyMet[i].Target
			remeasurementRunner := &performanceMeasurementAccountingRunner{delegate: isolation.runner(baseRunner), counters: &state.Counters, limits: state.Limits}
			remeasured, measureErr := MeasurePerformanceTarget(ctx, remeasurementRunner, isolation.workspace.Path, descriptors[target.ID], target, state.Limits, env, prepared.Packet.PacketDigest, manifest.BenchmarkDigest, currentPerformanceEnvironment(env).Identity)
			if _, publishErr := store.PublishState(*state, token); publishErr != nil {
				_ = isolation.cleanup()
				return out, publishErr
			}
			if measureErr != nil {
				alreadyMet[i].Comparison.Outcome = PerformanceTargetInconclusive
				alreadyMet[i].FinalQualification = PerformanceQualification{Reason: measureErr.Error()}
				continue
			}
			remeasurements[target.ID] = remeasured
			comparison, compareErr := ComparePerformanceTarget(target, baselineMeasurement(baseline, target.ID).Qualification.Median, remeasured.Qualification.Median, remeasured.Qualification.Qualified, false)
			if compareErr != nil {
				alreadyMet[i].Comparison.Outcome = PerformanceTargetBlocked
				alreadyMet[i].FinalQualification = PerformanceQualification{Reason: compareErr.Error()}
				continue
			}
			alreadyMet[i].Comparison, alreadyMet[i].FinalQualification = comparison, remeasured.Qualification
		}
		if err := ValidatePerformanceRegressionSet(selected, current[selected.ID], candidate, alreadyMet); err != nil {
			_ = publishPerformanceRejection(store, state, token, cycle, selected.ID, err)
			_ = isolation.cleanup()
			continue
		}
		if cleanupErr := isolation.cleanup(); cleanupErr != nil {
			return out, cleanupErr
		}
		currentIdentity, err := targetIdentity(prepared.Target.Path)
		if err != nil || currentIdentity != identity {
			return out, fmt.Errorf("canonical source changed before performance apply")
		}
		operations := make([]RepairApplyOperation, 0, len(changed))
		for index, path := range changed {
			preimage, readErr := os.ReadFile(filepath.Join(prepared.Target.Path, filepath.FromSlash(path)))
			if readErr != nil || hashBytes(preimage) != preimages[path] {
				return out, errors.Join(fmt.Errorf("canonical preimage changed before performance apply"), readErr)
			}
			preimagePath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, fmt.Sprintf("preimage-%06d.bin", index+1))
			preimageRef, publishErr := store.PublishBytes(preimagePath, "cycle-apply-preimage", preimage, true, token)
			if publishErr != nil {
				return out, publishErr
			}
			operations = append(operations, RepairApplyOperation{Path: path, PreimageDigest: preimageRef.Digest, PreimagePath: preimageRef.Path, PostimageDigest: hashBytes(replacements[path])})
		}
		journal := PerformanceApplyJournal{SchemaVersion: PerformanceSchemaVersion, Cycle: cycle, State: "planned", Before: identity, Operations: operations}
		journalPath, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "apply-journal.json")
		journalRef, err := store.PublishJSON(journalPath, "cycle-apply-journal", journal, false, token)
		if err != nil {
			return out, err
		}
		state.ApplyJournal, state.CurrentImplementation, state.UpdatedAt = &journalRef, identity, s.now().UTC()
		if _, err := store.PublishState(*state, token); err != nil {
			return out, err
		}
		applied, _, err := applyRepairFiles(prepared.Target.Path, replacements, preimages, state.Limits.ChangedFiles, state.Limits.ChangedBytes)
		if err != nil {
			journal.State = "uncertain"
			journal.Operations = mergeRepairApplyOperations(applied, operations)
			if ref, publishErr := store.PublishJSON(journalPath, "cycle-apply-journal", journal, false, token); publishErr == nil {
				state.ApplyJournal = &ref
				_, _ = store.PublishState(*state, token)
			}
			return out, err
		}
		identity, err = targetIdentity(prepared.Target.Path)
		if err != nil {
			return out, err
		}
		journal.State, journal.After, journal.Operations = "applied", identity, mergeRepairApplyOperations(applied, operations)
		journalRef, err = store.PublishJSON(journalPath, "cycle-apply-journal", journal, false, token)
		if err != nil {
			return out, err
		}
		current[selected.ID], out.Changed, out.FinalImplementation = candidate, true, identity
		for id, measurement := range remeasurements {
			current[id] = measurement
		}
		state.ApplyJournal, state.CurrentImplementation, state.AcceptedMutations, state.UpdatedAt = &journalRef, identity, state.AcceptedMutations+1, s.now().UTC()
		if _, err := store.PublishState(*state, token); err != nil {
			return out, err
		}
		if err := invalidateAfterPerformanceMutation(s.root, store.sprint); err != nil {
			return out, err
		}
	}
	out.Stalled = true
	return out, nil
}

type performanceMeasurementAccountingRunner struct {
	delegate    pprocess.Runner
	counters    *PerformanceCounters
	limits      PerformanceLimits
	invocations int
}

func (r *performanceMeasurementAccountingRunner) Run(ctx context.Context, request pprocess.Request) (pprocess.Result, error) {
	if r.counters.Commands >= r.limits.Commands {
		return pprocess.Result{}, fmt.Errorf("performance command limit exhausted")
	}
	r.counters.Commands++
	if r.invocations < r.limits.Warmups {
		r.counters.Warmups++
	} else {
		r.counters.Samples++
	}
	r.invocations++
	return r.delegate.Run(ctx, request)
}

func performanceOptimizationPrompt(target PerformanceTarget, profile PerformanceProfile) string {
	return fmt.Sprintf("Optimize exactly target %s (%s, %s %s %s) using retained profile %s. Modify approved production source only. Do not change tests, benchmarks, fixtures, configuration, governed inputs, evidence, repository controls, or Git data. Do not run shell or Git commands. Product code will derive the actual patch, run frozen correctness first, remeasure, and decide promotion.\n", target.ID, target.Metric, target.Comparator, target.Value, target.Unit, profile.Digest)
}
func baselineMeasurement(values []PerformanceMeasurement, id string) PerformanceMeasurement {
	for _, value := range values {
		if value.Target.ID == id {
			return value
		}
	}
	return PerformanceMeasurement{}
}
func performanceAlreadyMet(targets []PerformanceTarget, comparisons []PerformanceComparison, current map[string]PerformanceMeasurement) []PerformanceTargetResult {
	byID := map[string]PerformanceComparison{}
	for _, c := range comparisons {
		byID[c.TargetID] = c
	}
	var out []PerformanceTargetResult
	for _, t := range targets {
		if byID[t.ID].Outcome == PerformanceTargetMet {
			out = append(out, PerformanceTargetResult{Target: t, FinalQualification: current[t.ID].Qualification, Comparison: byID[t.ID]})
		}
	}
	return out
}

func derivePerformanceProductionProposal(canonical, isolated string, paths []string, limits PerformanceLimits) (map[string][]byte, map[string]string, int64, error) {
	normalized, err := ValidatePerformanceOptimizationScope(paths, 1, limits)
	if err != nil && !strings.Contains(err.Error(), "byte limit") {
		return nil, nil, 0, err
	}
	replacements, preimages := map[string][]byte{}, map[string]string{}
	var changedBytes int64
	for _, rel := range normalized {
		beforePath, afterPath := filepath.Join(canonical, filepath.FromSlash(rel)), filepath.Join(isolated, filepath.FromSlash(rel))
		before, beforeErr := os.ReadFile(beforePath)
		after, afterErr := os.ReadFile(afterPath)
		if errors.Is(beforeErr, fs.ErrNotExist) {
			return nil, nil, 0, fmt.Errorf("optimization cannot create production file %q", rel)
		}
		if beforeErr != nil || afterErr != nil {
			return nil, nil, 0, errors.Join(beforeErr, afterErr)
		}
		if err := ensureRepairRegularPath(canonical, beforePath); err != nil {
			return nil, nil, 0, err
		}
		if err := ensureRepairRegularPath(isolated, afterPath); err != nil {
			return nil, nil, 0, err
		}
		changedBytes += int64(len(before) + len(after))
		if changedBytes > limits.ChangedBytes {
			return nil, nil, 0, fmt.Errorf("optimization changed bytes exceed limit")
		}
		replacements[rel] = after
		preimages[rel] = hashBytes(before)
	}
	if _, err := ValidatePerformanceOptimizationScope(normalized, changedBytes, limits); err != nil {
		return nil, nil, 0, err
	}
	return replacements, preimages, changedBytes, nil
}
func renderPerformancePatch(canonical, isolated string, paths []string) string {
	var b strings.Builder
	for _, rel := range paths {
		before, _ := os.ReadFile(filepath.Join(canonical, filepath.FromSlash(rel)))
		after, _ := os.ReadFile(filepath.Join(isolated, filepath.FromSlash(rel)))
		writeWholeFilePatch(&b, rel, before, after)
	}
	return b.String()
}
func publishPerformanceRejection(store PerformanceStore, state *PerformanceState, token VerificationWriterToken, cycle int, target string, cause error) error {
	record := map[string]any{"schema_version": PerformanceSchemaVersion, "cycle": cycle, "target_id": target, "accepted": false, "reason": displayPerformanceCause(cause)}
	path, _ := PerformanceCycleRelPath(store.sprint, state.AttemptID, cycle, "rejection.json")
	_, err := store.PublishJSON(path, "cycle-rejection", record, true, token)
	return err
}
func invalidateAfterPerformanceMutation(root string, sp Sprint) error {
	flow, err := LoadFlowState(root, sp)
	if err != nil {
		return err
	}
	if flow.Review != nil {
		flow.Review.Stale = true
	}
	if flow.Smoke != nil {
		flow.Smoke.Stale = true
	}
	if flow.QA != nil {
		flow.QA.Fresh = false
	}
	if flow.Repair != nil {
		flow.Repair.Fresh = false
	}
	return SaveFlowState(root, sp, flow)
}

package app

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	kind         OperationKind
	fence        runcontrol.Fence
	ctx          context.Context
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	dispatched   bool
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	accepted, err = manager.DispatchOperation(deps.ctx, accepted.RunID)
	if err != nil {
		finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		_ = manager.FinishOperation(finishCtx, accepted.RunID, OperationFailed, err)
		return nil, classifiedCause(ExitRuntime, err, "run-control.dispatch")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) VerificationWriterToken() (sprint.VerificationWriterToken, func(sprint.VerificationWriterToken) error, error) {
	if c == nil {
		return sprint.VerificationWriterToken{}, nil, errors.New("durable verification ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	alias := digest
	var snapshot runcontrol.Snapshot
	var err error
	for retries := 0; ; retries++ {
		snapshot, err = m.repository.Accept(ctx, runcontrol.Acceptance{
			Target: target, ProductStatus: "prepared", OperationAlias: alias, ConfirmationDigest: digest,
		})
		if err == nil || digest == "" || !errors.Is(err, runcontrol.ErrConflict) {
			break
		}
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, alias)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		if existing.Lifecycle.IsActive() || existing.Lifecycle == runcontrol.LifecycleSucceeded {
			return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
		}
		if retries >= 31 {
			return AcceptedOperation{}, fmt.Errorf("operation retry chain exceeded its bound")
		}
		alias = durableOperationRetryAlias(alias, existing.RunID)
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{kind: req.Kind, fence: fence, ctx: operationCtx, cancel: cancel}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: "claimed"}, nil
}

func durableOperationRetryAlias(previous string, runID runcontrol.RunID) string {
	sum := sha256.Sum256([]byte(previous + "\x00" + string(runID)))
	return "retry-" + hex.EncodeToString(sum[:])
}

// DispatchOperation is the explicit hand-off from immutable confirmation to
// ownership control. AcceptOperation deliberately creates no goroutine, so a
// caller can publish confirmation under the claimed writer fence first.
func (m *durableOperationManager) DispatchOperation(ctx context.Context, runID string) (AcceptedOperation, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	owned := m.owned[runID]
	if owned == nil {
		return AcceptedOperation{}, runcontrol.ErrNotFound
	}
	if owned.dispatched {
		return AcceptedOperation{RunID: runID, Context: owned.ctx, Existing: true, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
	}
	owned.stop = make(chan struct{})
	owned.done = make(chan struct{})
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning), "transition": "dispatch"},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation dispatch persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation dispatch: %w", err)
	}
	owned.dispatched = true
	go m.controlOperation(owned.ctx, owned)
	return AcceptedOperation{RunID: runID, Context: owned.ctx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
		"code": event.Code, "severity": event.Severity, "project": event.Project, "sprint": event.Sprint,
		"repair_run_id": event.RepairRunID, "operation_run_id": event.OperationRunID, "operational_attempt_id": event.OperationalAttemptID,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	if event.FencingGeneration != 0 {
		payload["fencing_generation"] = fmt.Sprintf("%d", event.FencingGeneration)
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat := time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			var snapshot runcontrol.Snapshot
			err := retryRunControlOperation(ctx, func(callCtx context.Context) error {
				var snapshotErr error
				snapshot, snapshotErr = m.repository.Snapshot(callCtx, owned.fence.RunID)
				return snapshotErr
			})
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				err := retryRunControlOperation(ctx, func(callCtx context.Context) error {
					_, _, acknowledgeErr := m.repository.AcknowledgeCancellation(callCtx, owned.fence)
					return acknowledgeErr
				})
				if err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				err := retryRunControlOperation(ctx, func(callCtx context.Context) error {
					_, heartbeatErr := m.repository.Heartbeat(callCtx, owned.fence, runcontrol.OwnerLeaseDuration)
					return heartbeatErr
				})
				if err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	if owned.dispatched {
		close(owned.stop)
		<-owned.done
	}
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	if !owned.dispatched && owned.kind != OperationRepairPrepare {
		outcome, reason = runcontrol.TerminalPersistenceLost, "accepted operation was not confirmed and dispatched"
	} else {
		switch {
		case errors.Is(runErr, context.DeadlineExceeded):
			outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
		case errors.Is(runErr, context.Canceled), state == OperationCancelled:
			outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
		case runErr != nil, state == OperationFailed:
			outcome, reason = runcontrol.TerminalFailed, "operation failed"
		case state == OperationPartial:
			outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
		}
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

package app

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

// sharedOperationRunner is the single runtime-backed implementation used by
// terminal and browser adapters. Surface code owns presentation and
// confirmation; workflow semantics remain here and in the product services.
func sharedOperationRunner(deps dependencies, root workspace.Root, effective config.Effective, useCases dashboardUseCases) func(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error) {
	performanceLimits, performanceSources, _ := performanceSettings(effective)
	return func(ctx context.Context, req OperationRequest, emit func(OperationEvent)) (OperationResult, error) {
		result := OperationResult{State: OperationComplete, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}
		switch req.Kind {
		case OperationProjectReasoningFlow:
			rt, e := deps.sprintRuntimeFactory(effective.Config)
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := project.NewService(root.Path).WithRuntime(rt).ReasoningFlow(ctx, req.Project, project.ProjectReasoningStage(req.Stage))
			result.Message = fmt.Sprintf("project reasoning to=%s accepted=%t fresh=%t verdict=%s", r.To, r.Status.Accepted, r.Status.Fresh, r.Status.Verdict)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStage:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.FlowStage(ctx, req.Project, req.Sprint, stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			}))
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationFlow:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			flow := stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			})
			flow.Review = sprint.ReviewRequest{Restart: req.RestartReview}
			flow.Smoke = sprint.SmokeRequest{NonInteractive: true, OverrideConfirmed: req.ForceReview, ForceReview: req.ForceReview, OverrideRationale: req.OverrideRationale}
			flow.Merge = sprint.MergeRequest{Confirm: true, ModelOverride: req.Model}
			r, e := runSprintFlow(ctx, service, req.Project, req.Sprint, flow)
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationExecuteStart, OperationExecuteResume:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Execute(ctx, req.Project, req.Sprint, sprint.ExecuteRequest{TaskID: req.Task, ModelOverride: req.Model, Resume: req.Kind == OperationExecuteResume})
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationReviewStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Review(ctx, req.Project, req.Sprint, sprint.ReviewRequest{Concurrency: req.Parallelism, Focus: req.ReviewFocus, Restart: req.RestartReview, ModelOverride: req.Model, Progress: func(p sprint.ReviewProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: "review", Task: p.CoverageID, Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s", r.Status, r.Verdict)
			for _, f := range r.Findings {
				result.Findings = append(result.Findings, DisplayFinding{Severity: f.Severity, Section: "review", Problem: f.Title, Cause: f.Detail, Suggestion: f.Action})
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationSmokeStart:
			service := sprint.NewService(root.Path).WithPublisher(stagePublisher(effective.Config)).WithVerificationRuntime(performanceVerificationRuntime(effective.Config)).WithPerformanceLimits(performanceLimits, performanceSources).WithSmokeSettings(smokeSettings(effective, envLookup(deps.env)))
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, Progress: func(p sprint.SmokeProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Phase), Task: operationFirstNonEmpty(p.Test, p.Suite), Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s run=%s next=%s", r.Status, r.Verdict, r.RunID, r.NextAction)
			if r.Artifact != "" {
				if preview, readErr := useCases.PreviewArtifact(ctx, r.Artifact); readErr == nil {
					result.Content, result.Truncated = boundContent(preview.Content)
				}
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationVerifyStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.Verify(ctx, req.Project, req.Sprint, sprint.VerifyRequest{To: sprint.PlanningStage(req.Stage), Review: sprint.ReviewRequest{Focus: req.ReviewFocus, Restart: req.RestartReview}, Smoke: sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale}, Progress: func(p sprint.FlowProgress) {
				summary := displaySafe(p.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Stage), Message: p.State + ": " + summary, PhaseState: p.State, SafeSummary: summary})
			}})
			result.Message = fmt.Sprintf("assessment=%s next=%s", r.Verification.Assessment, r.Verification.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationPerformanceStart, OperationPerformanceResume, OperationPerformanceRecover:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service := useCases.sprintService().WithVerificationWriterFence(fence)
			if req.Kind == OperationPerformanceStart || req.Kind == OperationPerformanceResume {
				service, e = sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
				if e != nil {
					return failedOperation(result, e)
				}
				service = service.WithVerificationWriterFence(fence)
			}
			var r sprint.PerformanceResult
			if req.Kind == OperationPerformanceRecover {
				r, e = service.RecoverPerformance(ctx, req.Project, req.Sprint, token)
			} else {
				acceptedAt := time.Now().UTC()
				prepared, prepareErr := service.PreparePerformance(req.Project, req.Sprint, false)
				if prepareErr != nil {
					return failedOperation(result, prepareErr)
				}
				if !prepared.Ready {
					return failedOperation(result, fmt.Errorf("performance admission blocked: %s", strings.Join(prepared.Missing, "; ")))
				}
				manifest := sprint.PerformanceBenchmarkManifest{}
				authoringAttempts := 0
				if req.Kind == OperationPerformanceStart {
					manifest, authoringAttempts, e = service.PreparePerformanceManifest(ctx, req.Project, req.Sprint, prepared, environmentList(deps.env), acceptedAt, token)
					if e != nil {
						return failedOperation(result, e)
					}
				}
				r, e = service.RunPerformance(ctx, req.Project, req.Sprint, sprint.PerformanceRunRequest{WriterToken: token, Manifest: manifest, Environment: environmentList(deps.env), AuthoringAttempts: authoringAttempts, AcceptedAt: acceptedAt, Resume: req.Kind == OperationPerformanceResume})
			}
			result.RunID = token.RunID
			result.SemanticOutcome = string(r.Outcome)
			result.Message = fmt.Sprintf("attempt=%s outcome=%s next=%s", r.AttemptID, r.Outcome, r.NextAction)
			if e != nil {
				return failedOperation(result, sprint.ClassifyPerformanceError("performance.run", e))
			}
		case OperationPerformanceCancel:
			state, e := useCases.sprintService().PerformanceStatus(req.Project, req.Sprint)
			if e != nil {
				return failedOperation(result, e)
			}
			if useCases.runs == nil {
				return failedOperation(result, ErrWebUnavailable)
			}
			snapshot, _, cancelErr := useCases.runs.CancelRun(ctx, RunID(state.Correlation.RunID), "user_requested")
			result.RunID, result.Message = string(snapshot.RunID), "performance cancellation requested"
			if cancelErr != nil {
				return failedOperation(result, cancelErr)
			}
		case OperationQAStart, OperationQAResume:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			service = service.WithQAWriterFence(fence)
			r, e := service.RunQA(ctx, req.Project, req.Sprint, sprint.QARunRequest{Resume: req.Kind == OperationQAResume, FocusShard: req.Task, Suite: req.Suite, EvidenceProducing: req.Suite == "", WriterToken: token, Progress: func(progress sprint.QAProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Phase), Task: progress.ShardID, Message: progress.Message, Action: progress.Event, Reason: string(progress.ShardPhase), Detail: string(progress.ShardKind), Completed: progress.Completed, Total: progress.Total})
			}})
			result.Message = fmt.Sprintf("phase=%s shards=%d/%d next=%s", r.State.Phase, r.State.CompletedShards, r.State.TotalShards, r.State.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationRepairPrepare:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			budgets, budgetSources, e := repairBudgetsFor(effective, req.RepairMode)
			if e != nil {
				return failedOperation(result, e)
			}
			if req.RepairMaxCycles > 0 && req.RepairMaxCycles < budgets.MaxCycles {
				budgets.MaxCycles = req.RepairMaxCycles
				if budgets.MaxMutationCycles > budgets.MaxCycles {
					budgets.MaxMutationCycles = budgets.MaxCycles
				}
			}
			service := useCases.sprintService().WithQAWriterFence(fence)
			r, e := service.PrepareRepair(ctx, req.Project, req.Sprint, sprint.RepairPrepareRequest{IssueID: req.RepairIssueID, Mode: req.RepairMode, Budgets: budgets, BudgetSources: budgetSources, WriterToken: token})
			result.RunID = r.State.Run.RunID
			result.Message = fmt.Sprintf("repair=%s packet=%s phase=%s next=%s", r.Packet.RepairRunID, r.Packet.PacketDigest, r.State.Phase, r.State.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationRepairStart, OperationRepairResume:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			service = service.WithQAWriterFence(fence)
			run := sprint.RepairRunRequest{RepairRunID: req.RepairRunID, WriterToken: token, Progress: func(progress sprint.RepairProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(sprint.VerificationPhaseRepair), Task: req.RepairRunID, Message: progress.Message, PhaseState: string(progress.Phase), Action: string(progress.Gate), Completed: progress.Cycle, Total: 1})
			}}
			var r sprint.RepairResult
			if req.Kind == OperationRepairResume {
				r, e = service.ResumeRepair(ctx, req.Project, req.Sprint, run)
			} else {
				r, e = service.RunRepair(ctx, req.Project, req.Sprint, run)
			}
			result.RunID = token.RunID
			result.SemanticOutcome = string(r.Outcome)
			result.Message = fmt.Sprintf("repair=%s outcome=%s stop=%s cleanup=%t next=%s", r.RepairRunID, r.Outcome, r.StopReason, r.CleanupComplete, r.NextAction)
			e = repairSemanticOutcomeError(r, e)
			severity := "info"
			if r.Outcome == sprint.RepairOutcomeEscalated {
				severity = "critical"
			} else if r.Outcome == sprint.RepairOutcomeFailed || r.Outcome == sprint.RepairOutcomeBlocked || r.Outcome == sprint.RepairOutcomeStalled {
				severity = "error"
			}
			emit(OperationEvent{State: operationStateForError(e), Stage: string(sprint.VerificationPhaseRepair), Task: r.RepairRunID, Code: "repair.terminal." + string(r.Outcome), Severity: severity, Project: req.Project, Sprint: req.Sprint, RepairRunID: r.RepairRunID, OperationRunID: token.RunID, OperationalAttemptID: token.OperationalAttemptID, FencingGeneration: token.FencingGeneration, Action: "terminal", Reason: string(r.StopReason), SafeSummary: displaySafe(result.Message)})
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationRepairRecover:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service := useCases.sprintService().WithQAWriterFence(fence)
			r, e := service.RecoverRepair(ctx, req.Project, req.Sprint, sprint.RepairRecoverRequest{RepairRunID: req.RepairRunID, WriterToken: token})
			result.RunID = token.RunID
			result.SemanticOutcome = string(r.Outcome)
			result.Message = fmt.Sprintf("repair=%s recovery_outcome=%s stop=%s cleanup=%t next=%s", r.RepairRunID, r.Outcome, r.StopReason, r.CleanupComplete, r.NextAction)
			severity := "info"
			if r.Outcome == sprint.RepairOutcomeEscalated {
				severity = "critical"
			} else if r.Outcome != sprint.RepairOutcomeVerified && r.Outcome != sprint.RepairOutcomeVerifiedWithFindings {
				severity = "error"
			}
			emit(OperationEvent{State: operationStateForError(e), Stage: string(sprint.VerificationPhaseRepair), Task: r.RepairRunID, Code: "repair.recovery." + string(r.Outcome), Severity: severity, Project: req.Project, Sprint: req.Sprint, RepairRunID: r.RepairRunID, OperationRunID: token.RunID, OperationalAttemptID: token.OperationalAttemptID, FencingGeneration: token.FencingGeneration, Action: "terminal", Reason: string(r.StopReason), SafeSummary: displaySafe(result.Message)})
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationRepairCampaignStart:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			budgets, sources, e := repairBudgetsFor(effective, sprint.RepairModeAutomatic)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			campaign, e := service.WithQAWriterFence(fence).RunRepairCampaign(ctx, req.Project, req.Sprint, sprint.RepairCampaignRequest{Confirmer: req.RepairConfirmer, Budgets: budgets, Sources: sources, WriterToken: token, Progress: func(p sprint.RepairCampaignProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: "repair-campaign", Task: fmt.Sprintf("worker-%d/issue-%d", p.Worker, p.Issue), Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.RunID = token.RunID
			result.Message = fmt.Sprintf("campaign=%s status=%s workers=%d issues=%d/%d", campaign.ID, campaign.Status, len(campaign.Workers), campaign.Completed, campaign.Total)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyStart, OperationStudyResume:
			flags := runAllFlags{}
			flags.parallelism = &req.Parallelism
			flags.model = req.Model
			service, parallel, summary, e := runLoopService(deps, root, flags)
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.RunLoop(ctx, study.RunLoopRequest{StudyRef: req.Study, DimensionRefs: req.Dimensions, SourceRefs: req.Sources, Parallelism: parallel, Model: studyModelOverride(deps, flags.model), Config: summary, Continue: req.Kind == OperationStudyResume, Command: []string{"ultraplan", "operation"}, Progress: func(p study.RunLoopProgress) {
				stats := operationTaskStats(p.Task, time.Now().UTC())
				event := OperationEvent{State: OperationRunning, Task: p.Task.ID, Stage: string(p.Event), Message: strings.TrimSpace(p.Task.DimensionRef + " " + p.Task.Source), Completed: p.ScopeCounts.Completed, Total: p.ScopeCounts.Total, Attempt: p.Task.Attempts, RuntimeAttempts: stats.RuntimeAttempts, Turns: stats.Turns, TurnsKnown: stats.TurnsKnown, Tokens: stats.Tokens, TokensKnown: stats.TokensKnown, InputTokens: stats.InputTokens, OutputTokens: stats.OutputTokens, ReasoningTokens: stats.ReasoningTokens, CacheReadTokens: stats.CacheReadTokens, CacheWriteTokens: stats.CacheWriteTokens, Duration: stats.Duration, Provider: stats.Provider, Model: stats.Model, Harness: stats.Runtime, Cost: stats.Cost, RuntimeEvents: stats.Events}
				if p.RuntimeEvent != nil {
					applyRuntimeObservation(&event, *p.RuntimeEvent)
					event.Message = runtimeProgressSummary(*p.RuntimeEvent)
				}
				emit(event)
			}})
			result.Message = string(r.Status)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyCancel:
			service := study.NewService(root.Path)
			listing, e := service.ListStudy(req.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			info, e := study.CancelRunLoop(listing.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			result.Message = fmt.Sprintf("cancellation requested from run-loop process %d", info.PID)
		default:
			return failedOperation(result, fmt.Errorf("unsupported runtime operation %q", req.Kind))
		}
		emit(OperationEvent{State: OperationComplete, Message: "operation complete"})
		return result, nil
	}
}

// stageFlowRequest builds the sprint flow request for a stage or flow
// operation. A requested model applies to the selected target stage and, as a
// fallback for stages without dedicated per-stage handling (code-context), as
// the generic model override. Empty models keep configured defaults.
func stageFlowRequest(req OperationRequest, progress func(sprint.FlowProgress)) sprint.FlowRequest {
	flow := sprint.FlowRequest{To: sprint.PlanningStage(req.Stage), ModelOverride: req.Model}
	if req.Model != "" && req.Stage != "" {
		stage := sprint.PlanningStage(req.Stage)
		if _, ok := flow.StageOverrides[stage]; !ok {
			flow.StageOverrides = map[sprint.PlanningStage]sprint.StageRuntime{}
		}
		override := flow.StageOverrides[stage]
		override.Model = req.Model
		flow.StageOverrides[stage] = override
	}
	flow.Progress = progress
	return flow
}

