func (s Service) PreparePerformance(projectRef, sprintRef string, dryRun bool) (PerformancePrepareResult, error) {
	sp, inputs, catalog, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformancePrepareResult{}, err
	}
	policy := catalog.PerformancePolicy
	limits := s.performanceLimits
	if limits.TargetRows == 0 {
		limits = DefaultPerformanceLimits()
	}
	result := PerformancePrepareResult{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, PolicyMode: string(policy.Mode), PolicyDigest: policy.SourceDigest, Enabled: policy.Enabled(), DryRun: dryRun, Limits: limits, LimitSources: clonePerformanceSources(s.performanceLimitSources)}
	if s.performanceLimitsErr != nil {
		result.Missing = append(result.Missing, "Invalid effective performance limits: "+s.performanceLimitsErr.Error())
	}
	if !policy.Enabled() {
		result.NextAction = "Enable Performance Policy in project-index.md to use this optional phase."
		if markdownHeadingPresent(inputs.Requirements, "Performance Targets") {
			result.Missing = []string{"Performance Targets are declared while project policy is disabled."}
			result.NextAction = "Enable Performance Policy or remove the Performance Targets table."
		}
		return result, nil
	}
	packet, findings := ParsePerformanceTargets(inputs.Requirements)
	packet = BindPerformancePacketPolicy(packet, policy.SourceDigest)
	result.Packet = packet
	result.CorrectnessCommands = [][]string{{"go", "test", "./..."}, {"go", "test", "-race", "./..."}, {"go", "build", "./cmd/ultraplan"}}
	for _, finding := range findings {
		result.Missing = append(result.Missing, finding.Problem+": "+finding.Cause)
	}
	if len(packet.Targets) == 0 {
		result.Missing = append(result.Missing, "No valid performance target is declared.")
	}
	for _, target := range packet.Targets {
		if target.Samples > result.Limits.SampleCeiling {
			result.Missing = append(result.Missing, fmt.Sprintf("Target %s requires %d samples, above the effective ceiling %d.", target.ID, target.Samples, result.Limits.SampleCeiling))
		}
	}
	requiredCommands := 2 * len(result.CorrectnessCommands)
	for _, target := range packet.Targets {
		requiredCommands += 2 * (result.Limits.Warmups + target.Samples)
	}
	if requiredCommands > result.Limits.Commands {
		result.Missing = append(result.Missing, fmt.Sprintf("The complete no-change measurement requires %d commands, above the effective attempt limit %d.", requiredCommands, result.Limits.Commands))
	}
	if err := s.requireCompleteExecute(projectRef, sprintRef); err != nil {
		result.Missing = append(result.Missing, err.Error())
	}
	target, targetFindings := s.resolveSprintTarget(sp, inputs.ProjectIndex, false)
	for _, finding := range targetFindings {
		result.Missing = append(result.Missing, finding.Problem+": "+finding.Cause)
	}
	result.Target = target
	if target.Path != "" {
		if status, statusErr := gitOutput(target.Path, "status", "--porcelain", "--untracked-files=normal"); statusErr != nil {
			result.Missing = append(result.Missing, "Cannot inspect the performance target worktree.")
		} else if strings.TrimSpace(status) != "" && !performanceBenchmarkOnlyStatus(target.Path, status, packet) && !performanceRecordedTargetStatusAllowed(s.root, sp, target.Path) {
			result.Missing = append(result.Missing, "The performance target worktree has unrelated changes.")
		}
	}
	capabilities := pprocess.IsolationCapabilityFacts()
	if !capabilities.PrivateWorkspace || !capabilities.ContainedCopy || !capabilities.ProcessGroup || !capabilities.DescendantCleanup || !capabilities.WorkspaceRemoval {
		result.Missing = append(result.Missing, "The host cannot prove disposable-copy and process-tree cleanup support.")
	}
	result.ProtectedRoots = []string{sp.Path, filepath.Join(sp.Path, "verification"), filepath.Join(sp.Path, "requirements.md"), filepath.Join(sp.Path, "plan.md")}
	result.MutationPossible = true
	result.Ready = len(result.Missing) == 0
	if result.Ready {
		result.NextAction = "Start performance benchmark preparation."
	} else {
		result.NextAction = "Resolve the reported performance prerequisites and prepare again."
	}
	return result, nil
}

func performanceRecordedTargetStatusAllowed(root string, sp Sprint, target string) bool {
	state, err := LoadPerformanceState(root, sp)
	if err != nil || state.Result == nil {
		return false
	}
	result, err := NewPerformanceStore(root, sp).readResult(*state.Result)
	if err != nil {
		return false
	}
	identity, err := targetIdentity(target)
	return err == nil && result.FinalImplementation == identity
}

func performanceBenchmarkOnlyStatus(root, status string, packet PerformanceTargetPacket) bool {
	for _, line := range strings.Split(strings.TrimSpace(status), "\n") {
		if len(line) < 4 || line[:2] != "??" && line[:2] != "A " {
			return false
		}
		path := strings.TrimSpace(line[3:])
		if strings.Contains(path, " -> ") {
			return false
		}
		normalized, err := normalizeRepairPath(path)
		if err != nil || normalized != path || !strings.HasSuffix(strings.ToLower(path), "_test.go") && !strings.Contains(strings.ToLower(path), "/testdata/performance/") {
			return false
		}
	}
	manifest, err := DiscoverPerformanceManifest(root, packet)
	return err == nil && manifest.CoverageComplete
}

func clonePerformanceSources(values map[string]string) map[string]string {
	if len(values) == 0 {
		return nil
	}
	out := make(map[string]string, len(values))
	for key, value := range values {
		out[key] = value
	}
	return out
}

func (s Service) PerformanceStatus(projectRef, sprintRef string) (PerformanceState, error) {
	sp, inputs, catalog, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformanceState{}, err
	}
	if !catalog.PerformancePolicy.Enabled() {
		return PerformanceState{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, Phase: PerformancePhaseReady, Fresh: true, NextAction: "Performance is disabled for this project."}, nil
	}
	packet, findings := ParsePerformanceTargets(inputs.Requirements)
	packet = BindPerformancePacketPolicy(packet, catalog.PerformancePolicy.SourceDigest)
	state, err := LoadPerformanceState(s.root, sp)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			if len(findings) > 0 || len(packet.Targets) == 0 {
				return PerformanceState{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, Phase: PerformancePhaseStale, Fresh: false, FreshnessReasons: []string{"targets_invalid"}, TargetPacketDigest: packet.PacketDigest, Limits: effectivePerformanceLimits(s), NextAction: "Fix the Performance Targets table before starting performance."}, nil
			}
			return PerformanceState{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, Phase: PerformancePhaseReady, Fresh: true, TargetPacketDigest: packet.PacketDigest, Limits: effectivePerformanceLimits(s), NextAction: "Start performance benchmark preparation."}, nil
		}
		return PerformanceState{}, err
	}
	if len(findings) > 0 || packet.PacketDigest != state.TargetPacketDigest {
		state.Fresh = false
		state.Phase = PerformancePhaseStale
		state.FreshnessReasons = append(state.FreshnessReasons, "targets_changed")
	}
	if state.Freshness.RequirementsDigest != "" && state.Freshness.RequirementsDigest != packet.RequirementsDigest {
		appendPerformanceFreshnessReason(&state, "requirements_changed")
	}
	if state.Freshness.PolicyDigest != "" && state.Freshness.PolicyDigest != catalog.PerformancePolicy.SourceDigest {
		appendPerformanceFreshnessReason(&state, "policy_changed")
	}
	if state.Freshness.ExecuteDigest != "" {
		if digest, digestErr := performanceExecuteDigest(sp); digestErr != nil || digest != state.Freshness.ExecuteDigest {
			appendPerformanceFreshnessReason(&state, "execute_evidence_changed")
		}
	}
	if state.Manifest != nil && state.Freshness.ManifestDigest != "" {
		manifest, manifestErr := DiscoverPerformanceManifest(stateTargetPath(s, sp, inputs.ProjectIndex), packet)
		if manifestErr != nil || manifest.BenchmarkDigest != state.Freshness.ManifestDigest {
			appendPerformanceFreshnessReason(&state, "benchmark_changed")
		}
	}
	if state.Environment != nil && state.Freshness.EnvironmentIdentity != "" && currentPerformanceEnvironment(os.Environ()).Identity != state.Freshness.EnvironmentIdentity {
		appendPerformanceFreshnessReason(&state, "environment_changed")
	}
	if state.Freshness.RunnerVersion != "" && state.Freshness.RunnerVersion != PerformanceRunnerVersion || state.Freshness.ParserVersion != "" && state.Freshness.ParserVersion != PerformanceParserVersion {
		appendPerformanceFreshnessReason(&state, "instrument_changed")
	}
	correctness, marshalErr := json.Marshal([][]string{{"go", "test", "./..."}, {"go", "test", "-race", "./..."}, {"go", "build", "./cmd/ultraplan"}})
	if marshalErr != nil {
		return PerformanceState{}, fmt.Errorf("marshal performance correctness policy: %w", marshalErr)
	}
	if state.Freshness.CorrectnessDigest != "" && state.Freshness.CorrectnessDigest != hashBytes(correctness) {
		appendPerformanceFreshnessReason(&state, "correctness_policy_changed")
	}
	if state.Result != nil && state.Freshness.ResultDigest != "" && state.Freshness.ResultDigest != state.Result.Digest {
		appendPerformanceFreshnessReason(&state, "terminal_result_changed")
	}
	if target, targetFindings := s.resolveSprintTarget(sp, inputs.ProjectIndex, false); len(targetFindings) == 0 && target.Path != "" && state.Result != nil {
		if head, headErr := targetIdentity(target.Path); headErr == nil {
			result, resultErr := NewPerformanceStore(s.root, sp).readResult(*state.Result)
			if resultErr != nil || result.FinalImplementation != head {
				state.Fresh = false
				state.Phase = PerformancePhaseStale
				state.FreshnessReasons = append(state.FreshnessReasons, "implementation_changed")
			}
		}
	}
	if !state.Fresh {
		state.NextAction = "Run performance again against the current requirements and implementation."
	}
	return state, nil
}

func (s Service) RunPerformance(ctx context.Context, projectRef, sprintRef string, req PerformanceRunRequest) (result PerformanceResult, resultErr error) {
	if err := req.WriterToken.Validate(); err != nil {
		return PerformanceResult{}, err
	}
	prepared, err := s.PreparePerformance(projectRef, sprintRef, false)
	if err != nil {
		return PerformanceResult{}, err
	}
	if !prepared.Enabled {
		return PerformanceResult{}, fmt.Errorf("performance is disabled for this project")
	}
	if !prepared.Ready {
		return PerformanceResult{}, fmt.Errorf("performance admission blocked: %s", strings.Join(prepared.Missing, "; "))
	}
	lockedCtx, release, lockErr := s.acquireMutationContext(ctx, projectRef, sprintRef)
	if lockErr != nil {
		return PerformanceResult{}, lockErr
	}
	defer release()
	ctx = lockedCtx
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformanceResult{}, err
	}
	fence := s.verificationWriterFence
	store := NewPerformanceStore(s.root, sp).WithWriterFence(fence)
	if err := store.checkWriter(req.WriterToken); err != nil {
		return PerformanceResult{}, err
	}
	now := s.now().UTC()
	acceptedAt := req.AcceptedAt.UTC()
	if req.AcceptedAt.IsZero() {
		acceptedAt = now
	}
	manifest := req.Manifest
	environment := currentPerformanceEnvironment(req.Environment)
	var state PerformanceState
	var packetRef, manifestRef, environmentRef PerformanceArtifactRef
	var attemptID string
	if req.Resume {
		state, err = LoadPerformanceState(s.root, sp)
		if err != nil {
			return PerformanceResult{}, err
		}
		if state.Phase == PerformancePhaseTerminal && state.Result != nil {
			return store.readResult(*state.Result)
		}
		if !state.Fresh || state.Phase != PerformancePhaseBaseline && state.Phase != PerformancePhaseOptimizing && state.Phase != PerformancePhaseFinalizing {
			return PerformanceResult{}, fmt.Errorf("performance state has no resumable proven boundary")
		}
		if !now.Before(state.Deadline) {
			return PerformanceResult{}, fmt.Errorf("performance deadline expired; recover the interrupted attempt")
		}
		if state.TargetPacketDigest != prepared.Packet.PacketDigest || state.Manifest == nil || state.Environment == nil {
			return PerformanceResult{}, fmt.Errorf("performance resume identity drift")
		}
		packetRef, manifestRef, environmentRef, attemptID = state.Packet, *state.Manifest, *state.Environment, state.AttemptID
		if err := store.ReadJSON(manifestRef, &manifest); err != nil {
			return PerformanceResult{}, err
		}
		if err := store.ReadJSON(environmentRef, &environment); err != nil {
			return PerformanceResult{}, err
		}
		if environment.Identity != currentPerformanceEnvironment(req.Environment).Identity {
			return PerformanceResult{}, fmt.Errorf("performance environment drift prevents resume")
		}
		state.Correlation, state.UpdatedAt = req.WriterToken, now
		if _, err := store.PublishState(state, req.WriterToken); err != nil {
			return PerformanceResult{}, err
		}
	} else {
		if req.AuthoringAttempts < 0 || req.AuthoringAttempts > prepared.Limits.AuthoringAttempts {
			return PerformanceResult{}, fmt.Errorf("performance authoring attempts exceed the persisted limit")
		}
		if !now.Before(acceptedAt.Add(prepared.Limits.WallTime)) {
			return PerformanceResult{}, context.DeadlineExceeded
		}
		if err := ValidatePerformanceManifest(prepared.Packet, &manifest); err != nil {
			return PerformanceResult{}, err
		}
		attemptID = newPerformanceAttemptID(sp, req.WriterToken, now)
		packetPath, _ := PerformanceAttemptRelPath(sp, attemptID, "target-packet.json")
		packetRef, err = store.PublishJSON(packetPath, "target-packet", prepared.Packet, true, req.WriterToken)
		if err != nil {
			return PerformanceResult{}, err
		}
		manifestPath, _ := PerformanceAttemptRelPath(sp, attemptID, "benchmark-manifest.json")
		manifestRef, err = store.PublishJSON(manifestPath, "benchmark-manifest", manifest, true, req.WriterToken)
		if err != nil {
			return PerformanceResult{}, err
		}
		environmentPath, _ := PerformanceAttemptRelPath(sp, attemptID, "environment.json")
		environmentRef, err = store.PublishJSON(environmentPath, "environment", environment, true, req.WriterToken)
		if err != nil {
			return PerformanceResult{}, err
		}
		state = PerformanceState{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, AttemptID: attemptID, Phase: PerformancePhaseBaseline, Fresh: true, Correlation: req.WriterToken, Deadline: acceptedAt.Add(prepared.Limits.WallTime), Limits: prepared.Limits, Counters: PerformanceCounters{RuntimeAttempts: req.AuthoringAttempts}, Packet: packetRef, TargetPacketDigest: prepared.Packet.PacketDigest, Manifest: &manifestRef, Environment: &environmentRef, Freshness: newPerformanceFreshness(sp, prepared, manifest, environment), NextAction: "Measure the frozen baseline.", UpdatedAt: now}
		if _, err := store.PublishState(state, req.WriterToken); err != nil {
			return PerformanceResult{}, err
		}
	}
	if err := ValidatePerformanceManifest(prepared.Packet, &manifest); err != nil {
		return PerformanceResult{}, err
	}
	head, err := targetIdentity(prepared.Target.Path)
	if err != nil {
		return PerformanceResult{}, err
	}
	if state.Freshness.InitialImplementation == "" {
		state.Freshness.InitialImplementation = head
		state.CurrentImplementation = head
		if _, err := store.PublishState(state, req.WriterToken); err != nil {
			return PerformanceResult{}, err
		}
	}
	remaining := state.Deadline.Sub(s.now().UTC())
	if remaining <= 0 {
		return PerformanceResult{}, fmt.Errorf("performance deadline expired; recover the interrupted attempt")
	}
	deadlineCtx, cancelDeadline := context.WithTimeout(ctx, remaining)
	defer cancelDeadline()
	ctx = deadlineCtx
	descriptors := map[string]PerformanceDescriptor{}
	for _, descriptor := range manifest.Descriptors {
		for _, id := range descriptor.TargetIDs {
			descriptors[id] = descriptor
		}
	}
	baseRunner := s.processRunner
	if baseRunner == nil {
		baseRunner = pprocess.DirectRunner{}
	}
	runner := baseRunner
	var isolation performanceIsolation
	isolationActive := false
	defer func() {
		if isolationActive {
			if cleanupErr := isolation.cleanup(); cleanupErr != nil {
				result = PerformanceResult{}
				resultErr = errors.Join(resultErr, fmt.Errorf("performance cleanup uncertain: %w", cleanupErr))
			}
		}
	}()
	finishFailure := func(cause error) (PerformanceResult, error) {
		if isolationActive {
			if cleanupErr := isolation.cleanup(); cleanupErr != nil {
				cause = errors.Join(cause, cleanupErr)
			}
			isolationActive = false
		}
		return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, cause, req.WriterToken)
	}
	baseline := make([]PerformanceMeasurement, 0, len(prepared.Packet.Targets))
	var baselineRef PerformanceArtifactRef
	if state.Baseline != nil {
		baselineRef = *state.Baseline
		if err := store.ReadJSON(baselineRef, &baseline); err != nil {
			return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, fmt.Errorf("read frozen baseline: %w", err), req.WriterToken)
		}
		if len(baseline) != len(prepared.Packet.Targets) {
			return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, fmt.Errorf("frozen baseline target coverage is incomplete"), req.WriterToken)
		}
	} else {
		isolation, err = createPerformanceIsolation(ctx, prepared.Target.Path, prepared.ProtectedRoots, prepared.Limits)
		if err != nil {
			return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, err, req.WriterToken)
		}
		isolationActive = true
		runner = isolation.runner(baseRunner)
		measurementRoot := isolation.workspace.Path
		if err := runPerformanceCorrectness(ctx, runner, measurementRoot, prepared.CorrectnessCommands, prepared.Limits, req.Environment, &state.Counters); err != nil {
			return finishFailure(fmt.Errorf("baseline correctness failed: %w", err))
		}
		for _, target := range prepared.Packet.Targets {
			measurement, measureErr := MeasurePerformanceTarget(ctx, runner, measurementRoot, descriptors[target.ID], target, prepared.Limits, req.Environment, prepared.Packet.PacketDigest, manifest.BenchmarkDigest, environment.Identity)
			if measureErr != nil {
				return finishFailure(measureErr)
			}
			baseline = append(baseline, measurement)
			state.Counters.Commands += prepared.Limits.Warmups + target.Samples
			state.Counters.Warmups += prepared.Limits.Warmups
			state.Counters.Samples += target.Samples
		}
		baselinePath, _ := PerformanceAttemptRelPath(sp, attemptID, "baseline.json")
		baselineRef, err = store.PublishJSON(baselinePath, "baseline", baseline, true, req.WriterToken)
		if err != nil {
			return PerformanceResult{}, err
		}
		state.Baseline, state.Phase, state.NextAction, state.UpdatedAt = &baselineRef, PerformancePhaseFinalizing, "Measure the final canonical implementation.", s.now().UTC()
		if _, err := store.PublishState(state, req.WriterToken); err != nil {
			return PerformanceResult{}, err
		}
		if err := isolation.assertUnchanged(ctx); err != nil {
			return finishFailure(err)
		}
		if err := isolation.cleanup(); err != nil {
			isolationActive = false
			return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, err, req.WriterToken)
		}
		isolationActive = false
	}
	optimization, optimizeErr := s.optimizePerformance(ctx, prepared, manifest, baseline, store, &state, req.WriterToken, req.Environment)
	if optimizeErr != nil {
		return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, head, optimizeErr, req.WriterToken)
	}
	finalHead := optimization.FinalImplementation
	if finalHead == "" {
		finalHead = head
	}
	isolation, err = createPerformanceIsolation(ctx, prepared.Target.Path, prepared.ProtectedRoots, prepared.Limits)
	if err != nil {
		return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, finalHead, err, req.WriterToken)
	}
	isolationActive = true
	runner = isolation.runner(baseRunner)
	measurementRoot := isolation.workspace.Path
	state.Phase, state.NextAction, state.UpdatedAt = PerformancePhaseFinalizing, "Measure the final canonical implementation.", s.now().UTC()
	if _, err := store.PublishState(state, req.WriterToken); err != nil {
		return PerformanceResult{}, err
	}
	comparisons := make([]PerformanceComparison, 0, len(prepared.Packet.Targets))
	finalMeasurements := make([]PerformanceMeasurement, 0, len(prepared.Packet.Targets))
	targetResults := make([]PerformanceTargetResult, 0, len(prepared.Packet.Targets))
	var outcomes []PerformanceTargetOutcome
	var misses []string
	for i, target := range prepared.Packet.Targets {
		finalMeasurement, measureErr := MeasurePerformanceTarget(ctx, runner, measurementRoot, descriptors[target.ID], target, prepared.Limits, req.Environment, prepared.Packet.PacketDigest, manifest.BenchmarkDigest, environment.Identity)
		if measureErr != nil {
			return finishFailure(measureErr)
		}
		finalMeasurements = append(finalMeasurements, finalMeasurement)
		state.Counters.Commands += prepared.Limits.Warmups + target.Samples
		state.Counters.Warmups += prepared.Limits.Warmups
		state.Counters.Samples += target.Samples
		comparison, compareErr := ComparePerformanceTarget(target, baseline[i].Qualification.Median, finalMeasurement.Qualification.Median, finalMeasurement.Qualification.Qualified, false)
		if compareErr != nil {
			return PerformanceResult{}, compareErr
		}
		comparisons = append(comparisons, comparison)
		targetResults = append(targetResults, PerformanceTargetResult{Target: target, BaselineQualification: baseline[i].Qualification, FinalQualification: finalMeasurement.Qualification, Comparison: comparison})
		outcomes = append(outcomes, comparison.Outcome)
		if comparison.Outcome == PerformanceTargetMissed {
			misses = append(misses, target.ID)
		}
	}
	if err := runPerformanceCorrectness(ctx, runner, measurementRoot, prepared.CorrectnessCommands, prepared.Limits, req.Environment, &state.Counters); err != nil {
		failure := fmt.Errorf("final correctness failed: %w", err)
		return finishFailure(failure)
	}
	if err := isolation.assertUnchanged(ctx); err != nil {
		return finishFailure(err)
	}
	if err := isolation.cleanup(); err != nil {
		isolationActive = false
		return s.finishPerformanceFailure(store, sp, prepared, state, packetRef, manifestRef, environmentRef, finalHead, err, req.WriterToken)
	}
	isolationActive = false
	finalPath, _ := PerformanceAttemptRelPath(sp, attemptID, "final.json")
	finalRef, err := store.PublishJSON(finalPath, "final", finalMeasurements, true, req.WriterToken)
	if err != nil {
		return PerformanceResult{}, err
	}
	outcome := DerivePerformanceRunOutcome(outcomes, false, false, false, optimization.Stalled)
	next := "Performance passed. Conformance Review may run."
	if outcome == PerformanceTargetMiss {
		next = "Profile the missed required targets and run a bounded performance attempt."
	} else if outcome == PerformancePassedWithReports {
		next = "Inspect report-only measurements, then run Conformance Review."
	} else if outcome != PerformancePassed {
		next = "Resolve the performance blocker and run performance again."
	}
	initialImplementation := state.Freshness.InitialImplementation
	if initialImplementation == "" {
		initialImplementation = head
	}
	result = PerformanceResult{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, AttemptID: attemptID, Outcome: outcome, Comparisons: comparisons, TargetResults: targetResults, Counters: state.Counters, Packet: packetRef, Manifest: manifestRef, Environment: environmentRef, Baseline: baselineRef, Final: finalRef, InitialImplementation: initialImplementation, FinalImplementation: finalHead, UnresolvedMisses: misses, NextAction: next, CompletedAt: s.now().UTC()}
	resultPath, _ := PerformanceAttemptRelPath(sp, attemptID, "result.json")
	resultRef, err := store.PublishJSON(resultPath, "result", result, true, req.WriterToken)
	if err != nil {
		return PerformanceResult{}, err
	}
	state.Freshness.FinalImplementation, state.Freshness.ResultDigest = finalHead, resultRef.Digest
	if err := store.checkWriter(req.WriterToken); err != nil {
		return PerformanceResult{}, err
	}
	if err := atomicWriteFile(filepath.Join(sp.Path, "performance.md"), []byte(renderPerformanceReport(prepared.Packet.Targets, baseline, result))); err != nil {
		return PerformanceResult{}, err
	}
	state.Final, state.Result, state.Outcome, state.Phase, state.NextAction, state.UpdatedAt = &finalRef, &resultRef, outcome, PerformancePhaseTerminal, next, result.CompletedAt
	stateRef, err := store.PublishState(state, req.WriterToken)
	if err != nil {
		return PerformanceResult{}, err
	}
	flow, err := LoadFlowState(s.root, sp)
	if err != nil {
		return PerformanceResult{}, err
	}
	flow.Performance = performanceFlowSummary(state, stateRef, prepared.Packet.Targets, result.Comparisons)
	if err := store.checkWriter(req.WriterToken); err != nil {
		return PerformanceResult{}, err
	}
	if err := SaveFlowState(s.root, sp, flow); err != nil {
		return PerformanceResult{}, err
	}
	if err := store.PruneTerminalAttempts(attemptID, prepared.Limits.RetainedAttempts); err != nil {
		return result, fmt.Errorf("prune terminal performance attempts: %w", err)
	}
	return result, nil
}

func effectivePerformanceLimits(s Service) PerformanceLimits {
	if s.performanceLimits.TargetRows == 0 {
		return DefaultPerformanceLimits()
	}
	return s.performanceLimits
}

func appendPerformanceFreshnessReason(state *PerformanceState, reason string) {
	for _, existing := range state.FreshnessReasons {
		if existing == reason {
			state.Fresh = false
			state.Phase = PerformancePhaseStale
			return
		}
	}
	state.FreshnessReasons = append(state.FreshnessReasons, reason)
	state.Fresh = false
	state.Phase = PerformancePhaseStale
}

func stateTargetPath(s Service, sp Sprint, projectIndex string) string {
	target, findings := s.resolveSprintTarget(sp, projectIndex, false)
	if len(findings) != 0 {
		return ""
	}
	return target.Path
}

func newPerformanceFreshness(sp Sprint, prepared PerformancePrepareResult, manifest PerformanceBenchmarkManifest, environment PerformanceEnvironment) PerformanceFreshness {
	executeDigest, _ := performanceExecuteDigest(sp)
	correctness, _ := json.Marshal(prepared.CorrectnessCommands)
	processPolicy := hashBytes([]byte(strings.Join([]string{PerformanceRunnerVersion, PerformanceParserVersion, "serial-v1", "median-v1", "cv-v1"}, "\x00")))
	return PerformanceFreshness{RequirementsDigest: prepared.Packet.RequirementsDigest, PolicyDigest: prepared.PolicyDigest, ExecuteDigest: executeDigest, PacketDigest: prepared.Packet.PacketDigest, ManifestDigest: manifest.BenchmarkDigest, RunnerVersion: PerformanceRunnerVersion, ParserVersion: PerformanceParserVersion, CorrectnessDigest: hashBytes(correctness), ProcessPolicyDigest: processPolicy, EnvironmentIdentity: environment.Identity, WorkflowDigest: hashBytes([]byte("performance-v1:prepare,freeze,baseline,optimize,final,correctness,publish"))}
}

func performanceExecuteDigest(sp Sprint) (string, error) {
	paths := []string{filepath.Join(sp.Path, "execute.md"), filepath.Join(sp.Path, ".run-state.json")}
	h := sha256.New()
	for _, path := range paths {
		data, err := os.ReadFile(path)
		if err != nil {
			return "", err
		}
		fmt.Fprintf(h, "%s\x00%s\n", filepath.Base(path), hashBytes(data))
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func (s Service) finishPerformanceFailure(store PerformanceStore, sp Sprint, prepared PerformancePrepareResult, state PerformanceState, packet, manifest, environment PerformanceArtifactRef, implementation string, cause error, token VerificationWriterToken) (PerformanceResult, error) {
	outcome := PerformanceBlocked
	next := "Resolve the performance blocker and run performance again."
	if errors.Is(cause, context.Canceled) {
		outcome = PerformanceCancelled
		next = "Performance was cancelled after cleanup. Run performance again when ready."
	} else if errors.Is(cause, context.DeadlineExceeded) {
		outcome = PerformanceStalled
		next = "The performance deadline was exhausted. Inspect retained evidence before starting again."
	}
	if strings.Contains(strings.ToLower(cause.Error()), "cleanup is uncertain") {
		outcome = PerformanceCleanupUncertain
		next = "Reconcile descendant cleanup before starting or resuming performance work."
	}
	comparisons := make([]PerformanceComparison, 0, len(prepared.Packet.Targets))
	targetResults := make([]PerformanceTargetResult, 0, len(prepared.Packet.Targets))
	for _, target := range prepared.Packet.Targets {
		comparison := PerformanceComparison{TargetID: target.ID, Outcome: PerformanceTargetBlocked, Reason: "measurement did not reach a qualified terminal boundary"}
		comparisons = append(comparisons, comparison)
		targetResults = append(targetResults, PerformanceTargetResult{Target: target, Comparison: comparison})
	}
	completed := s.now().UTC()
	initialImplementation := state.Freshness.InitialImplementation
	if initialImplementation == "" {
		initialImplementation = implementation
	}
	result := PerformanceResult{SchemaVersion: PerformanceSchemaVersion, Project: sp.Project, Sprint: sp.Slug, AttemptID: state.AttemptID, Outcome: outcome, Comparisons: comparisons, TargetResults: targetResults, Counters: state.Counters, Packet: packet, Manifest: manifest, Environment: environment, InitialImplementation: initialImplementation, FinalImplementation: implementation, NextAction: next, CompletedAt: completed}
	if state.Baseline != nil {
		result.Baseline = *state.Baseline
	}
	if state.Final != nil {
		result.Final = *state.Final
	}
	resultPath, _ := PerformanceAttemptRelPath(sp, state.AttemptID, "result.json")
	resultRef, publishErr := store.PublishJSON(resultPath, "result", result, true, token)
	if publishErr != nil {
		return result, errors.Join(cause, publishErr)
	}
	if err := store.checkWriter(token); err != nil {
		return result, errors.Join(cause, err)
	}
	if err := atomicWriteFile(filepath.Join(sp.Path, "performance.md"), []byte(renderPerformanceReport(prepared.Packet.Targets, nil, result))); err != nil {
		return result, errors.Join(cause, err)
	}
	state.Result, state.Outcome, state.Phase, state.Blocker, state.NextAction, state.UpdatedAt = &resultRef, outcome, PerformancePhaseTerminal, displayPerformanceCause(cause), next, completed
	state.Freshness.FinalImplementation, state.Freshness.ResultDigest = implementation, resultRef.Digest
	stateRef, stateErr := store.PublishState(state, token)
	if stateErr != nil {
		return result, errors.Join(cause, stateErr)
	}
	flow, flowErr := LoadFlowState(s.root, sp)
	if flowErr == nil {
		flow.Performance = performanceFlowSummary(state, stateRef, prepared.Packet.Targets, comparisons)
		flowErr = SaveFlowState(s.root, sp, flow)
	}
	if flowErr == nil {
		flowErr = store.PruneTerminalAttempts(state.AttemptID, prepared.Limits.RetainedAttempts)
	}
	return result, errors.Join(cause, flowErr)
}

func displayPerformanceCause(err error) string {
	value := strings.TrimSpace(err.Error())
	if len(value) > 512 {
		value = value[:512]
	}
	return value
}

func runPerformanceCorrectness(ctx context.Context, runner pprocess.Runner, root string, commands [][]string, limits PerformanceLimits, env []string, counters *PerformanceCounters) error {
	for _, command := range commands {
		if len(command) == 0 || counters.Commands >= limits.Commands {
			return fmt.Errorf("performance command limit exhausted")
		}
		request := pprocess.Request{Executable: command[0], Args: append([]string(nil), command[1:]...), Dir: filepath.Clean(root), Env: allowPerformanceEnvironment(env), Timeout: limits.CommandTimeout, StdoutLimit: limits.StdoutBytes, StderrLimit: limits.StderrBytes, CleanupGrace: limits.CleanupReserve}
		counters.Commands++
		result, err := runner.Run(ctx, request)
		if !result.CleanupComplete {
			return fmt.Errorf("correctness process cleanup is uncertain")
		}
		if err != nil {
			return err
		}
		if result.StdoutTruncated || result.StderrTruncated {
			return fmt.Errorf("correctness output was truncated")
		}
	}
	return nil
}

func (s Service) PerformanceCurrentResult(projectRef, sprintRef string) (PerformanceResult, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformanceResult{}, err
	}
	state, err := s.PerformanceStatus(projectRef, sprintRef)
	if err != nil {
		return PerformanceResult{}, err
	}
	if state.Result == nil {
		return PerformanceResult{}, fmt.Errorf("performance result is unavailable")
	}
	return NewPerformanceStore(s.root, sp).readResult(*state.Result)
}

func (s Service) PerformanceEvidence(projectRef, sprintRef, cursor, filter string, limit int) (PerformanceEvidencePage, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	state, err := LoadPerformanceState(s.root, sp)
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	if len(filter) > 64 || strings.ContainsAny(filter, "\x00/\\") {
		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance evidence filter")
	}
	if limit == 0 {
		limit = state.Limits.EvidencePageSize
	}
	prefix := performanceCursorPrefix(state.AttemptID, filter)
	rawCursor := ""
	if cursor != "" {
		parts := strings.SplitN(cursor, ":", 2)
		if len(parts) != 2 || parts[0] != prefix {
			return PerformanceEvidencePage{}, fmt.Errorf("performance evidence cursor does not match attempt and filter")
		}
		rawCursor = parts[1]
	}
	page, err := NewPerformanceStore(s.root, sp).EvidencePage(state.AttemptID, rawCursor, filter, limit)
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	if page.NextCursor != "" {
		page.NextCursor = prefix + ":" + page.NextCursor
	}
	return page, nil
}

func performanceCursorPrefix(attemptID, filter string) string {
	sum := sha256.Sum256([]byte(attemptID + "\x00" + filter))
	return hex.EncodeToString(sum[:8])
}

// RecoverPerformance reconciles retained publication facts without starting a
// runtime or process. It can complete summary/state/flow publication from one
// valid immutable result, but never derives a successful result from samples.
func (s Service) RecoverPerformance(ctx context.Context, projectRef, sprintRef string, token VerificationWriterToken) (PerformanceResult, error) {
	lockedCtx, release, err := s.acquireMutationContext(ctx, projectRef, sprintRef)
	if err != nil {
		return PerformanceResult{}, err
	}
	defer release()
	if err := lockedCtx.Err(); err != nil {
		return PerformanceResult{}, err
	}
	sp, inputs, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return PerformanceResult{}, err
	}
	store := NewPerformanceStore(s.root, sp).WithWriterFence(s.verificationWriterFence)
	if err := store.checkWriter(token); err != nil {
		return PerformanceResult{}, err
	}
	state, err := LoadPerformanceState(s.root, sp)
	if err != nil {
		return PerformanceResult{}, err
	}
	state.Correlation = token
	var resultRef PerformanceArtifactRef
	if state.Result != nil {
		resultRef = *state.Result
	} else {
		rel, _ := PerformanceAttemptRelPath(sp, state.AttemptID, "result.json")
		path, resolveErr := store.resolve(rel)
		if resolveErr != nil {
			return PerformanceResult{}, resolveErr
		}
		data, readErr := os.ReadFile(path)
		if errors.Is(readErr, fs.ErrNotExist) && state.ApplyJournal != nil {
			return s.recoverPerformanceApply(sp, inputs.ProjectIndex, state, store, token)
		}
		if readErr != nil {
			return PerformanceResult{}, fmt.Errorf("no immutable terminal result is available for recovery: %w", readErr)
		}
		resultRef = PerformanceArtifactRef{Path: rel, Digest: hashBytes(data)}
	}
	result, err := store.readResult(resultRef)
	if err != nil {
		return PerformanceResult{}, fmt.Errorf("recover immutable performance result: %w", err)
	}
	if result.AttemptID != state.AttemptID || result.Project != sp.Project || result.Sprint != sp.Slug {
		return PerformanceResult{}, fmt.Errorf("recovery result identity does not match current state")
	}
	var packet PerformanceTargetPacket
	if err := store.ReadJSON(state.Packet, &packet); err != nil {
		return PerformanceResult{}, err
	}
	var baseline []PerformanceMeasurement
	if state.Baseline != nil {
		if err := store.ReadJSON(*state.Baseline, &baseline); err != nil {
			return PerformanceResult{}, err
		}
	}
	if err := atomicWriteFile(filepath.Join(sp.Path, "performance.md"), []byte(renderPerformanceReport(packet.Targets, baseline, result))); err != nil {
		return PerformanceResult{}, err
	}
	state.Correlation, state.Result, state.Outcome, state.Phase, state.Fresh, state.Blocker, state.NextAction, state.UpdatedAt = token, &resultRef, result.Outcome, PerformancePhaseTerminal, true, "", result.NextAction, s.now().UTC()
	state.Freshness.FinalImplementation, state.Freshness.ResultDigest = result.FinalImplementation, resultRef.Digest
	stateRef, err := store.PublishState(state, token)
	if err != nil {
		return PerformanceResult{}, err
	}
	flow, err := LoadFlowState(s.root, sp)
	if err != nil {
		return PerformanceResult{}, err
	}
	flow.Performance = performanceFlowSummary(state, stateRef, packet.Targets, result.Comparisons)
	if err := SaveFlowState(s.root, sp, flow); err != nil {
		return PerformanceResult{}, err
	}
	if err := store.PruneTerminalAttempts(state.AttemptID, state.Limits.RetainedAttempts); err != nil {
		return PerformanceResult{}, err
	}
	return result, nil
}

func (s Service) recoverPerformanceApply(sp Sprint, projectIndex string, state PerformanceState, store PerformanceStore, token VerificationWriterToken) (PerformanceResult, error) {
	target, findings := s.resolveSprintTarget(sp, projectIndex, false)
	if len(findings) != 0 || target.Path == "" {
		return PerformanceResult{}, fmt.Errorf("performance recovery cannot resolve the canonical target")
	}
	var journal PerformanceApplyJournal
	if err := store.ReadJSON(*state.ApplyJournal, &journal); err != nil {
		return PerformanceResult{}, err
	}
	if err := ValidatePerformanceApplyJournal(journal); err != nil {
		return PerformanceResult{}, err
	}
	if journal.Cycle != state.Counters.OptimizationCycles {
		return PerformanceResult{}, fmt.Errorf("performance recovery journal does not match the current cycle")
	}
	_, complete := reconcilePerformanceJournal(store, target.Path, filepath.Dir(state.ApplyJournal.Path), &journal)
	journalPath, _ := PerformanceCycleRelPath(sp, state.AttemptID, journal.Cycle, "apply-journal.json")
	journalRef, err := store.PublishJSON(journalPath, "cycle-apply-journal", journal, false, token)
	if err != nil {
		return PerformanceResult{}, err
	}
	state.ApplyJournal, state.CurrentImplementation, state.UpdatedAt = &journalRef, journal.Before, s.now().UTC()
	if _, err := store.PublishState(state, token); err != nil {
		return PerformanceResult{}, err
	}
	var packet PerformanceTargetPacket
	if err := store.ReadJSON(state.Packet, &packet); err != nil {
		return PerformanceResult{}, err
	}
	if state.Manifest == nil || state.Environment == nil {
		return PerformanceResult{}, fmt.Errorf("performance recovery lacks frozen manifest or environment")
	}
	prepared := PerformancePrepareResult{Project: sp.Project, Sprint: sp.Slug, Packet: packet, Target: target, Limits: state.Limits}
	cause := errors.New("interrupted performance apply was compensated from retained preimages")
	if !complete {
		cause = errors.New("performance apply cleanup is uncertain after interrupted recovery")
	}
	result, finishErr := s.finishPerformanceFailure(store, sp, prepared, state, state.Packet, *state.Manifest, *state.Environment, journal.Before, cause, token)
	if finishErr != nil {
		terminal, loadErr := LoadPerformanceState(s.root, sp)
		if loadErr != nil || terminal.Result == nil {
			return result, finishErr
		}
	}
	return result, nil
}

func reconcilePerformanceJournal(store PerformanceStore, target, evidenceDir string, journal *PerformanceApplyJournal) (productionApplied, complete bool) {
	complete = true
	journal.State = "compensated"
	cyclePrefix := filepath.ToSlash(filepath.Clean(evidenceDir)) + "/"
	for index := range journal.Operations {
		operation := &journal.Operations[index]
		if !strings.HasPrefix(filepath.ToSlash(operation.PreimagePath), cyclePrefix) || !strings.HasPrefix(filepath.Base(operation.PreimagePath), "preimage-") {
			complete, journal.State = false, "uncertain"
			continue
		}
		targetPath := filepath.Join(target, filepath.FromSlash(operation.Path))
		if err := ensureRepairRegularPath(target, targetPath); err != nil {
			complete, journal.State = false, "uncertain"
			continue
		}
		current, readErr := os.ReadFile(targetPath)
		if readErr != nil {
			complete, journal.State = false, "uncertain"
			continue
		}
		switch hashBytes(current) {
		case operation.PreimageDigest:
			operation.Restored = operation.Applied
		case operation.PostimageDigest:
			productionApplied = true
			preimage, loadErr := store.ReadBytes(PerformanceArtifactRef{Path: operation.PreimagePath, Digest: operation.PreimageDigest})
			if loadErr != nil || privateAtomicWrite(targetPath, preimage, "performance-recover-compensate", QAStateHooks{}) != nil {
				complete, journal.State = false, "uncertain"
				continue
			}
			operation.Applied, operation.Restored = true, true
		default:
			complete, journal.State = false, "uncertain"
		}
	}
	if identity, err := targetIdentity(target); err != nil || identity != journal.Before {
		complete, journal.State = false, "uncertain"
	}
	return productionApplied, complete
}

func (s Service) requirePerformanceGate(projectRef, sprintRef string) error {
	_, _, catalog, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil || !catalog.PerformancePolicy.Enabled() {
		return err
	}
	state, err := s.PerformanceStatus(projectRef, sprintRef)
	if err != nil {
		return fmt.Errorf("performance evidence is required before Conformance Review: %w", err)
	}
	if !state.Fresh || state.Phase != PerformancePhaseTerminal || state.Outcome != PerformancePassed && state.Outcome != PerformancePassedWithReports {
		return fmt.Errorf("performance evidence does not permit Conformance Review: outcome=%s fresh=%t; %s", state.Outcome, state.Fresh, state.NextAction)
	}
	return nil
}

func currentPerformanceEnvironment(env []string) PerformanceEnvironment {
	allowed := allowPerformanceEnvironment(env)
	policy := sha256.Sum256([]byte(strings.Join(allowed, "\x00")))
	base := PerformanceEnvironment{OS: runtime.GOOS, Architecture: runtime.GOARCH, Runtime: runtime.Version(), Toolchain: runtime.Version(), ProcessPolicy: PerformanceRunnerVersion, EnvironmentPolicyDigest: hex.EncodeToString(policy[:]), NoiseControl: "serial-v1"}
	sum := sha256.Sum256([]byte(strings.Join([]string{base.OS, base.Architecture, base.Runtime, base.Toolchain, base.ProcessPolicy, base.EnvironmentPolicyDigest, base.NoiseControl}, "\x00")))
	base.Identity = hex.EncodeToString(sum[:])
	return base
}

func newPerformanceAttemptID(sp Sprint, token VerificationWriterToken, now time.Time) string {
	sum := sha256.Sum256([]byte(strings.Join([]string{sp.Project, sp.Slug, token.RunID, token.OperationalAttemptID, fmt.Sprint(token.FencingGeneration), now.Format(time.RFC3339Nano)}, "\x00")))
	return "performance-v1-attempt-" + hex.EncodeToString(sum[:12])
}

func performanceFlowSummary(state PerformanceState, stateRef PerformanceArtifactRef, targets []PerformanceTarget, comparisons []PerformanceComparison) *PerformanceFlowSummary {
	summary := &PerformanceFlowSummary{Phase: state.Phase, Fresh: state.Fresh, Outcome: state.Outcome, AttemptID: state.AttemptID, StatePath: stateRef.Path, StateDigest: stateRef.Digest, NextAction: state.NextAction}
	for _, target := range targets {
		if target.Gate == PerformanceRequired {
			summary.Required++
		} else {
			summary.Reports++
		}
	}
	for _, comparison := range comparisons {
		if comparison.Outcome == PerformanceTargetMet {
			summary.Met++
		}
		if comparison.Outcome == PerformanceTargetMissed {
			summary.Missed++
		}
	}
	return summary
}

func renderPerformanceReport(targets []PerformanceTarget, baseline []PerformanceMeasurement, result PerformanceResult) string {
	var b strings.Builder
	fmt.Fprintf(&b, "# Performance verification\n\nStatus: `%s`\n\n## Targets\n\n| ID | Scenario | Metric | Contract | Baseline | Candidate | Outcome |\n| --- | --- | --- | --- | ---: | ---: | --- |\n", result.Outcome)
	baseByID := map[string]string{}
	for _, measurement := range baseline {
		baseByID[measurement.Target.ID] = measurement.Qualification.Median
	}
	comparisonByID := map[string]PerformanceComparison{}
	for _, comparison := range result.Comparisons {
		comparisonByID[comparison.TargetID] = comparison
	}
	for _, target := range targets {
		comparison := comparisonByID[target.ID]
		fmt.Fprintf(&b, "| %s | %s | %s | %s %s %s | %s | %s | %s |\n", target.ID, escapePerformanceCell(target.Scenario), escapePerformanceCell(target.Metric), target.Comparator, target.Value, target.Unit, baseByID[target.ID], comparison.Candidate, comparison.Outcome)
	}
	fmt.Fprintf(&b, "\n## Change summary\n\n")
	if result.InitialImplementation == result.FinalImplementation {
		fmt.Fprintln(&b, "No implementation change was promoted in this attempt.")
	} else {
		fmt.Fprintf(&b, "A contained optimization was promoted from `%s` to `%s`.\n", result.InitialImplementation, result.FinalImplementation)
	}
	b.WriteString("\n## Qualification\n\n")
	for _, target := range result.TargetResults {
		fmt.Fprintf(&b, "- `%s`: baseline qualified=%t, final qualified=%t, final CV=%g%%\n", target.Target.ID, target.BaselineQualification.Qualified, target.FinalQualification.Qualified, target.FinalQualification.CVPercent)
	}
	b.WriteString("\n## Blockers\n\n")
	if result.Outcome == PerformanceBlocked || result.Outcome == PerformanceCleanupUncertain {
		fmt.Fprintln(&b, "The retained result records a blocking authority or cleanup failure.")
	} else {
		fmt.Fprintln(&b, "None.")
	}
	fmt.Fprintf(&b, "\n## Evidence\n\n- Target packet: `%s`\n- Benchmark manifest: `%s`\n- Environment: `%s`\n- Baseline: `%s`\n- Final: `%s`\n- Commands: `%d`\n- Runtime attempts: `%d`\n\n## Next action\n\n%s\n", result.Packet.Path, result.Manifest.Path, result.Environment.Path, result.Baseline.Path, result.Final.Path, result.Counters.Commands, result.Counters.RuntimeAttempts, result.NextAction)
	return b.String()
}

func escapePerformanceCell(value string) string {
	value = strings.ReplaceAll(value, "|", "\\|")
	return strings.ReplaceAll(strings.ReplaceAll(value, "\r", " "), "\n", " ")
}

func (store PerformanceStore) readResult(ref PerformanceArtifactRef) (PerformanceResult, error) {
	path, err := store.resolve(ref.Path)
	if err != nil {
		return PerformanceResult{}, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return PerformanceResult{}, err
	}
	if hashBytes(data) != ref.Digest {
		return PerformanceResult{}, fmt.Errorf("performance result digest mismatch")
	}
	var result PerformanceResult
	decoder := jsonNewStrictDecoder(data)
	if err := decoder(&result); err != nil {
		return PerformanceResult{}, err
	}
	return result, nil
}

func jsonNewStrictDecoder(data []byte) func(any) error {
	return func(target any) error {
		decoder := json.NewDecoder(strings.NewReader(string(data)))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(target); err != nil {
			return err
		}
		if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
			return fmt.Errorf("trailing JSON data")
		}
		return nil
	}
}

package sprint

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
)

const performanceHardStateBytes = 128 << 20
const performanceEvidenceScanLimit = 4096

var performanceAttemptID = regexp.MustCompile(`^performance-v1-attempt-[a-f0-9]{24}$`)

type PerformanceStore struct {
	root   string
	sprint Sprint
	fence  func(VerificationWriterToken) error
	hooks  QAStateHooks
}

func (store PerformanceStore) ReadJSON(ref PerformanceArtifactRef, value any) error {
	data, err := store.ReadBytes(ref)
	if err != nil {
		return err
	}
	return jsonNewStrictDecoder(data)(value)
}

func (store PerformanceStore) ReadBytes(ref PerformanceArtifactRef) ([]byte, error) {
	path, err := store.resolve(ref.Path)
	if err != nil {
		return nil, err
	}
	if err := performanceNoFollow(path, store.sprint.Path); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) == 0 || len(data) > performanceHardStateBytes || hashBytes(data) != ref.Digest {
		return nil, fmt.Errorf("performance artifact digest mismatch")
	}
	return data, nil
}

type PerformanceEvidenceRecord struct {
	AttemptID string `json:"attempt_id"`
	Name      string `json:"name"`
	Path      string `json:"path"`
	Digest    string `json:"digest"`
	Size      int64  `json:"size_bytes"`
}

type PerformanceEvidencePage struct {
	Records    []PerformanceEvidenceRecord `json:"records"`
	NextCursor string                      `json:"next_cursor,omitempty"`
}

// EvidencePage performs a bounded, attempt-scoped metadata query. It never
// returns artifact contents or reconstructs state by walking old attempts.
func (store PerformanceStore) EvidencePage(attemptID, cursor, filter string, limit int) (PerformanceEvidencePage, error) {
	if !performanceAttemptID.MatchString(attemptID) {
		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance attempt ID")
	}
	if limit <= 0 || limit > MaxPerformanceLimits().EvidencePageSize {
		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance evidence page size")
	}
	baseRel, _ := PerformanceAttemptRelPath(store.sprint, attemptID, "placeholder")
	base, err := store.resolve(filepath.Dir(baseRel))
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	capacity := limit * 2
	if capacity > performanceEvidenceScanLimit {
		capacity = performanceEvidenceScanLimit
	}
	names := make([]string, 0, capacity)
	scanned := 0
	err = filepath.WalkDir(base, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path == base {
			return nil
		}
		scanned++
		if scanned > performanceEvidenceScanLimit {
			return fmt.Errorf("performance evidence scan exceeds %d entries", performanceEvidenceScanLimit)
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("performance evidence contains a symbolic link")
		}
		if entry.IsDir() {
			return nil
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("performance evidence contains a non-regular record")
		}
		rel, relErr := filepath.Rel(base, path)
		if relErr != nil {
			return relErr
		}
		name := filepath.ToSlash(rel)
		if strings.Contains(name, filter) {
			names = append(names, name)
		}
		return nil
	})
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	sort.Strings(names)
	page := PerformanceEvidencePage{}
	for _, name := range names {
		if cursor != "" && name <= cursor {
			continue
		}
		if len(page.Records) == limit {
			page.NextCursor = page.Records[len(page.Records)-1].Name
			break
		}
		path := filepath.Join(base, filepath.FromSlash(name))
		info, statErr := os.Lstat(path)
		if statErr != nil || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 {
			return PerformanceEvidencePage{}, fmt.Errorf("unsafe performance evidence record %q", name)
		}
		if info.Size() <= 0 || info.Size() > performanceHardStateBytes {
			return PerformanceEvidencePage{}, fmt.Errorf("performance evidence record %q exceeds the query bound", name)
		}
		data, readErr := os.ReadFile(path)
		if readErr != nil {
			return PerformanceEvidencePage{}, readErr
		}
		rel := filepath.ToSlash(filepath.Join(filepath.Dir(baseRel), name))
		page.Records = append(page.Records, PerformanceEvidenceRecord{AttemptID: attemptID, Name: name, Path: rel, Digest: hashBytes(data), Size: info.Size()})
	}
	return page, nil
}

// PruneTerminalAttempts retains the newest bounded terminal attempts and never
// removes the current attempt. Nonterminal or malformed directories are left
// untouched for explicit recovery.
func (store PerformanceStore) PruneTerminalAttempts(current string, retain int) error {
	if retain <= 0 || retain > MaxPerformanceLimits().RetainedAttempts || !performanceAttemptID.MatchString(current) {
		return fmt.Errorf("invalid performance retention request")
	}
	baseRel := filepath.ToSlash(filepath.Join("projects", store.sprint.Project, "sprints", store.sprint.Slug, "verification", "performance", "attempts"))
	base, err := store.resolve(baseRel)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(base)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	type candidate struct {
		name string
		mod  time.Time
	}
	var values []candidate
	for _, entry := range entries {
		if !entry.IsDir() || !performanceAttemptID.MatchString(entry.Name()) {
			continue
		}
		resultRel, _ := PerformanceAttemptRelPath(store.sprint, entry.Name(), "result.json")
		resultPath, resolveErr := store.resolve(resultRel)
		if resolveErr != nil {
			continue
		}
		info, statErr := os.Lstat(resultPath)
		if statErr != nil || !info.Mode().IsRegular() {
			continue
		}
		values = append(values, candidate{name: entry.Name(), mod: info.ModTime()})
	}
	sort.Slice(values, func(i, j int) bool {
		if values[i].mod.Equal(values[j].mod) {
			return values[i].name > values[j].name
		}
		return values[i].mod.After(values[j].mod)
	})
	kept := map[string]bool{current: true}
	for _, value := range values {
		if len(kept) >= retain {
			break
		}
		kept[value.name] = true
	}
	for _, value := range values {
		if kept[value.name] {
			continue
		}
		path, resolveErr := store.resolve(filepath.ToSlash(filepath.Join(baseRel, value.name)))
		if resolveErr != nil {
			return resolveErr
		}
		if err := os.RemoveAll(path); err != nil {
			return err
		}
	}
	return nil
}

func NewPerformanceStore(root string, sprint Sprint) PerformanceStore {
	return PerformanceStore{root: root, sprint: sprint}
}

func (store PerformanceStore) WithWriterFence(fence func(VerificationWriterToken) error) PerformanceStore {
	store.fence = fence
	return store
}

func (store PerformanceStore) WithHooks(hooks QAStateHooks) PerformanceStore {
	store.hooks = hooks
	return store
}

func PerformanceStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "verification", "performance-state.json"))
}

func PerformanceReportRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "performance.md"))
}

func PerformanceAttemptRelPath(s Sprint, attemptID, name string) (string, error) {
	if !performanceAttemptID.MatchString(attemptID) {
		return "", fmt.Errorf("invalid performance attempt ID")
	}
	if name == "" || filepath.Base(name) != name || strings.ContainsAny(name, "\x00/\\") {
		return "", fmt.Errorf("invalid performance record name")
	}
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "verification", "performance", "attempts", attemptID, name)), nil
}

func PerformanceCycleRelPath(s Sprint, attemptID string, cycle int, name string) (string, error) {
	if cycle <= 0 {
		return "", fmt.Errorf("invalid performance cycle")
	}
	base, err := PerformanceAttemptRelPath(s, attemptID, "placeholder")
	if err != nil {
		return "", err
	}
	base = filepath.Dir(base)
	if name == "" || filepath.Base(name) != name || strings.ContainsAny(name, "\x00/\\") {
		return "", fmt.Errorf("invalid performance record name")
	}
	return filepath.ToSlash(filepath.Join(base, "cycles", fmt.Sprintf("%06d", cycle), name)), nil
}

func (store PerformanceStore) PublishJSON(rel, kind string, value any, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := store.checkWriter(token); err != nil {
		return PerformanceArtifactRef{}, err
	}
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return PerformanceArtifactRef{}, fmt.Errorf("encode performance %s: %w", kind, err)
	}
	data = append(data, '\n')
	return store.publishBytes(rel, kind, data, immutable, token)
}

func (store PerformanceStore) PublishBytes(rel, kind string, data []byte, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := store.checkWriter(token); err != nil {
		return PerformanceArtifactRef{}, err
	}
	return store.publishBytes(rel, kind, data, immutable, token)
}

func (store PerformanceStore) publishBytes(rel, kind string, data []byte, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if len(data) == 0 || len(data) > performanceHardStateBytes {
		return PerformanceArtifactRef{}, fmt.Errorf("performance %s exceeds the retained record limit", kind)
	}
	path, err := store.resolve(rel)
	if err != nil {
		return PerformanceArtifactRef{}, err
	}
	if err := performanceNoFollow(path, store.sprint.Path); err != nil {
		return PerformanceArtifactRef{}, err
	}
	if immutable {
		current, readErr := os.ReadFile(path)
		if readErr == nil {
			if bytes.Equal(current, data) {
				return PerformanceArtifactRef{Path: rel, Digest: hashBytes(data)}, nil
			}
			return PerformanceArtifactRef{}, fmt.Errorf("immutable performance %s already exists with different bytes", kind)
		}
		if !errors.Is(readErr, fs.ErrNotExist) {
			return PerformanceArtifactRef{}, fmt.Errorf("inspect performance %s: %w", kind, readErr)
		}
	}
	hooks := store.hooks
	beforeRename := hooks.BeforeRename
	hooks.BeforeRename = func(hookKind, hookPath string) error {
		if err := store.checkWriter(token); err != nil {
			return err
		}
		if beforeRename != nil {
			return beforeRename(hookKind, hookPath)
		}
		return nil
	}
	if hooks.BeforeStep != nil {
		if err := hooks.BeforeStep(kind, path); err != nil {
			return PerformanceArtifactRef{}, err
		}
	}
	var writeErr error
	if immutable {
		writeErr = privateImmutableWrite(path, data, "performance-"+kind, hooks)
	} else {
		writeErr = privateAtomicWrite(path, data, "performance-"+kind, hooks)
	}
	if errors.Is(writeErr, errImmutableRecordConflict) {
		return PerformanceArtifactRef{}, fmt.Errorf("immutable performance %s already exists with different bytes", kind)
	}
	if writeErr != nil {
		return PerformanceArtifactRef{}, fmt.Errorf("publish performance %s: %w", kind, writeErr)
	}
	return PerformanceArtifactRef{Path: rel, Digest: hashBytes(data)}, nil
}

func (store PerformanceStore) PublishState(state PerformanceState, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := validatePerformanceState(state, store.sprint); err != nil {
		return PerformanceArtifactRef{}, err
	}
	return store.PublishJSON(PerformanceStateRelPath(store.sprint), "state", state, false, token)
}

func LoadPerformanceState(root string, sprint Sprint) (PerformanceState, error) {
	path, err := resolveSprintContained(root, sprint, PerformanceStateRelPath(sprint))
	if err != nil {
		return PerformanceState{}, err
	}
	if err := performanceNoFollow(path, sprint.Path); err != nil {
		return PerformanceState{}, err
	}
	file, err := os.Open(path)
	if err != nil {
		return PerformanceState{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, performanceHardStateBytes+1))
	decoder.DisallowUnknownFields()
	var state PerformanceState
	if err := decoder.Decode(&state); err != nil {
		return PerformanceState{}, fmt.Errorf("decode performance state: %w", err)
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		return PerformanceState{}, fmt.Errorf("decode performance state: trailing data")
	}
	if err := validatePerformanceState(state, sprint); err != nil {
		return PerformanceState{}, err
	}
	return state, nil
}

func validatePerformanceState(state PerformanceState, sprint Sprint) error {
	if state.SchemaVersion != PerformanceSchemaVersion || state.Project != sprint.Project || state.Sprint != sprint.Slug || !performanceAttemptID.MatchString(state.AttemptID) {
		return fmt.Errorf("invalid performance state identity")
	}
	if err := state.Correlation.Validate(); err != nil {
		return err
	}
	if state.Deadline.IsZero() || state.UpdatedAt.IsZero() || strings.TrimSpace(state.NextAction) == "" || state.Packet.Path == "" || !validFingerprint(state.Packet.Digest) || !validFingerprint(state.TargetPacketDigest) {
		return fmt.Errorf("incomplete performance state")
	}
	if err := ValidatePerformanceLimits(state.Limits); err != nil {
		return err
	}
	if err := validatePerformanceCounters(state.Counters, state.Limits); err != nil {
		return err
	}
	if err := validatePerformanceStateRef(state, state.Packet, "target-packet.json", true); err != nil {
		return err
	}
	for _, ref := range []struct {
		value    *PerformanceArtifactRef
		name     string
		required bool
	}{{state.Manifest, "benchmark-manifest.json", state.Phase != PerformancePhasePreparing}, {state.Environment, "environment.json", state.Phase != PerformancePhasePreparing}, {state.Baseline, "baseline.json", state.Phase == PerformancePhaseOptimizing || state.Phase == PerformancePhaseFinalizing}, {state.Final, "final.json", false}, {state.Result, "result.json", state.Phase == PerformancePhaseTerminal}} {
		if ref.value == nil {
			if ref.required {
				return fmt.Errorf("performance state is missing %s", ref.name)
			}
			continue
		}
		if err := validatePerformanceStateRef(state, *ref.value, ref.name, true); err != nil {
			return err
		}
	}
	if state.ApplyJournal != nil {
		if state.Counters.OptimizationCycles <= 0 {
			return fmt.Errorf("performance state has an apply journal without a cycle")
		}
		want, pathErr := PerformanceCycleRelPath(sprint, state.AttemptID, state.Counters.OptimizationCycles, "apply-journal.json")
		if pathErr != nil || state.ApplyJournal.Path != want || !validFingerprint(state.ApplyJournal.Digest) {
			return fmt.Errorf("performance state has an invalid apply-journal reference")
		}
	}
	if state.AcceptedMutations < 0 || state.AcceptedMutations > state.Limits.OptimizationCycles {
		return fmt.Errorf("performance state has an invalid accepted-mutation count")
	}
	if state.CurrentImplementation != "" && !validFingerprint(state.CurrentImplementation) {
		return fmt.Errorf("performance state has an invalid current implementation")
	}
	for name, digest := range map[string]string{
		"requirements": state.Freshness.RequirementsDigest, "policy": state.Freshness.PolicyDigest,
		"execute": state.Freshness.ExecuteDigest, "packet": state.Freshness.PacketDigest,
		"manifest": state.Freshness.ManifestDigest, "correctness": state.Freshness.CorrectnessDigest,
		"process_policy": state.Freshness.ProcessPolicyDigest, "environment": state.Freshness.EnvironmentIdentity,
		"workflow": state.Freshness.WorkflowDigest, "initial_implementation": state.Freshness.InitialImplementation,
		"final_implementation": state.Freshness.FinalImplementation, "result": state.Freshness.ResultDigest,
	} {
		if digest != "" && !validFingerprint(digest) {
			return fmt.Errorf("performance state has an invalid %s freshness digest", name)
		}
	}
	switch state.Phase {
	case PerformancePhaseReady, PerformancePhasePreparing, PerformancePhaseBaseline, PerformancePhaseOptimizing, PerformancePhaseFinalizing, PerformancePhaseTerminal, PerformancePhaseStale:
	default:
		return fmt.Errorf("invalid performance state phase")
	}
	if state.Phase == PerformancePhaseTerminal && !validPerformanceRunOutcome(state.Outcome) {
		return fmt.Errorf("terminal performance state has an invalid outcome")
	}
	if len(state.FreshnessReasons) > 32 || len(state.Blocker) > 512 || len(state.NextAction) > 1024 {
		return fmt.Errorf("performance state text exceeds its bound")
	}
	return nil
}

func validatePerformanceCounters(counters PerformanceCounters, limits PerformanceLimits) error {
	if counters.Commands < 0 || counters.Commands > limits.Commands || counters.Warmups < 0 || counters.Warmups > counters.Commands || counters.Samples < 0 || counters.Samples > counters.Commands || counters.OptimizationCycles < 0 || counters.OptimizationCycles > limits.OptimizationCycles || counters.RuntimeAttempts < 0 {
		return fmt.Errorf("performance counters exceed the persisted attempt limits")
	}
	maxRuntimeAttempts := limits.AuthoringAttempts + limits.OptimizationCycles*limits.OptimizationAttempts
	if counters.RuntimeAttempts > maxRuntimeAttempts {
		return fmt.Errorf("performance runtime attempts exceed the persisted attempt limits")
	}
	return nil
}

func validatePerformanceStateRef(state PerformanceState, ref PerformanceArtifactRef, name string, required bool) error {
	if !required && ref.Path == "" && ref.Digest == "" {
		return nil
	}
	want, err := PerformanceAttemptRelPath(Sprint{Project: state.Project, Slug: state.Sprint}, state.AttemptID, name)
	if err != nil || ref.Path != want || !validFingerprint(ref.Digest) {
		return fmt.Errorf("performance state has an invalid %s reference", name)
	}
	return nil
}

func validPerformanceRunOutcome(outcome PerformanceRunOutcome) bool {
	switch outcome {
	case PerformancePassed, PerformancePassedWithReports, PerformanceTargetMiss, PerformanceBlocked, PerformanceStalled, PerformanceCancelled, PerformanceCleanupUncertain:
		return true
	default:
		return false
	}
}

func (store PerformanceStore) checkWriter(token VerificationWriterToken) error {
	if err := token.Validate(); err != nil {
		return fmt.Errorf("invalid performance writer: %w", err)
	}
	if store.fence == nil {
		return fmt.Errorf("no verification writer fence is configured")
	}
	if err := store.fence(token); err != nil {
		return fmt.Errorf("performance writer is stale: %w", err)
	}
	return nil
}

func (store PerformanceStore) resolve(rel string) (string, error) {
	return resolveSprintContained(store.root, store.sprint, rel)
}

func performanceNoFollow(path, sprintRoot string) error {
	cleanPath, cleanRoot := filepath.Clean(path), filepath.Clean(sprintRoot)
	if cleanPath != cleanRoot && !strings.HasPrefix(cleanPath, cleanRoot+string(filepath.Separator)) {
		return fmt.Errorf("performance path escapes sprint root")
	}
	for current := cleanPath; current != cleanRoot; current = filepath.Dir(current) {
		info, err := os.Lstat(current)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("performance path contains a symbolic link")
		}
	}
	return nil
}

package sprint

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type atomicWriteHooks struct {
	BeforeRename func(path string) error
}

func LoadFlowState(root string, s Sprint) (FlowState, error) {
	if state, found, err := loadFlowStateDatabase(root, s); err != nil {
		return FlowState{}, err
	} else if found {
		path, pathErr := FlowStatePath(root, s)
		if pathErr != nil {
			return FlowState{}, pathErr
		}
		switch state.SchemaVersion {
		case PreviousFlowStateSchemaVersion, OlderFlowStateSchemaVersion:
			state = migrateFlowStateV2(s, state)
		case LegacyFlowStateSchemaVersion:
			state = migrateFlowStateV1(root, s, state)
		case FlowStateSchemaVersion:
			if isPreCodeContextStages(state.Stages) {
				state.Stages = interpretPreCodeContextStages(s, state.Stages)
			}
		default:
			return FlowState{}, fmt.Errorf("%w: %s: schemaVersion %d; restore version %d or regenerate state", ErrFlowStateUnsupported, path, state.SchemaVersion, FlowStateSchemaVersion)
		}
		if err := ValidateFlowState(root, s, state, path); err != nil {
			return FlowState{}, err
		}
		return state, nil
	}
	path, err := FlowStatePath(root, s)
	if err != nil {
		return FlowState{}, err
	}
	content, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return FlowState{}, fmt.Errorf("%w: %s", ErrFlowStateMissing, path)
		}
		return FlowState{}, fmt.Errorf("read flow state %s: %w", path, err)
	}
	var header struct {
		SchemaVersion int `json:"schemaVersion"`
	}
	if err := json.Unmarshal(content, &header); err != nil {
		return FlowState{}, fmt.Errorf("%w: %s: %w", ErrFlowStateMalformed, path, err)
	}
	if header.SchemaVersion == 0 {
		return FlowState{}, fmt.Errorf("%w: %s: missing schemaVersion", ErrFlowStateMalformed, path)
	}
	if header.SchemaVersion != FlowStateSchemaVersion && header.SchemaVersion != PreviousFlowStateSchemaVersion && header.SchemaVersion != OlderFlowStateSchemaVersion && header.SchemaVersion != LegacyFlowStateSchemaVersion {
		return FlowState{}, fmt.Errorf("%w: %s: schemaVersion %d; restore version %d or regenerate state", ErrFlowStateUnsupported, path, header.SchemaVersion, FlowStateSchemaVersion)
	}
	var state FlowState
	dec := json.NewDecoder(bytes.NewReader(content))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return FlowState{}, fmt.Errorf("%w: %s: %w", ErrFlowStateMalformed, path, err)
	}
	var trailing any
	if err := dec.Decode(&trailing); err == nil {
		return FlowState{}, fmt.Errorf("%w: %s: multiple JSON values", ErrFlowStateMalformed, path)
	} else if !errors.Is(err, io.EOF) {
		return FlowState{}, fmt.Errorf("%w: %s: trailing JSON: %v", ErrFlowStateMalformed, path, err)
	}
	if header.SchemaVersion == PreviousFlowStateSchemaVersion || header.SchemaVersion == OlderFlowStateSchemaVersion {
		state = migrateFlowStateV2(s, state)
		if err := ValidateFlowState(root, s, state, path); err != nil {
			return FlowState{}, err
		}
	}
	if header.SchemaVersion == LegacyFlowStateSchemaVersion {
		state = migrateFlowStateV1(root, s, state)
		if err := ValidateFlowState(root, s, state, path); err != nil {
			return FlowState{}, err
		}
	}
	if header.SchemaVersion == FlowStateSchemaVersion && isPreCodeContextStages(state.Stages) {
		state.Stages = interpretPreCodeContextStages(s, state.Stages)
	}
	if err := ValidateFlowState(root, s, state, path); err != nil {
		return FlowState{}, err
	}
	return state, nil
}

func isPreCodeContextStages(stages []StageState) bool {
	if len(stages) != len(PlanningStages())-1 {
		return false
	}
	legacy := []PlanningStage{StageRequirements, StageSprintIndex, StageTechnicalHandbook, StageAreaReasoning, StageReasoning, StagePlan}
	for i := range legacy {
		if stages[i].Stage != legacy[i] {
			return false
		}
	}
	return true
}

func interpretPreCodeContextStages(sp Sprint, stages []StageState) []StageState {
	out := make([]StageState, 0, len(stages)+1)
	out = append(out, stages[0])
	inserted := StageState{Stage: StageCodeContext, Status: StatusMissing, Path: ArtifactRelPath(sp, StageCodeContext)}
	if stages[0].Status == StatusComplete {
		inserted.Status = StatusReady
		for _, later := range stages[1:] {
			if later.Status != StatusMissing {
				inserted.Status = StatusSkipped
				inserted.LastRunAt = stages[0].LastRunAt
				break
			}
		}
	}
	out = append(out, inserted)
	out = append(out, stages[1:]...)
	return out
}

func preCodeContextFlowState(root string, sp Sprint) bool {
	path, err := FlowStatePath(root, sp)
	if err != nil {
		return false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	var state FlowState
	return json.Unmarshal(data, &state) == nil && state.SchemaVersion == FlowStateSchemaVersion && isPreCodeContextStages(state.Stages)
}

// legacyFlowState reports the original versioned map-based planning state.
// It predates durable review/smoke attempt ownership, so recovery has no live
// attempt to reconcile and must preserve the file for compatibility.
func legacyFlowState(root string, s Sprint) bool {
	path, err := FlowStatePath(root, s)
	if err != nil {
		return false
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	var header struct {
		SchemaVersion int `json:"schemaVersion"`
		Version       int `json:"version"`
	}
	if err := json.Unmarshal(content, &header); err != nil {
		return false
	}
	return header.SchemaVersion == 0 && header.Version == 1
}

func migrateFlowStateV2(sp Sprint, state FlowState) FlowState {
	state.SchemaVersion = FlowStateSchemaVersion
	if isPreCodeContextStages(state.Stages) {
		state.Stages = interpretPreCodeContextStages(sp, state.Stages)
	}
	return state
}

func migrateFlowStateV1(root string, sp Sprint, state FlowState) FlowState {
	state.SchemaVersion = FlowStateSchemaVersion
	if isPreCodeContextStages(state.Stages) {
		state.Stages = interpretPreCodeContextStages(sp, state.Stages)
	}
	if state.Review != nil {
		r := state.Review
		r.Stale = true
		if r.Status == ReviewCompleted {
			digest, _ := hashFile(mustArtifactPath(root, sp, StageReview))
			if digest == "" {
				digest = "legacy-unverifiable"
			}
			if r.Fingerprint == "" {
				r.Fingerprint = "legacy-unverifiable"
			}
			completedAt := derefTime(r.LastRunAt)
			if completedAt.IsZero() {
				completedAt = state.UpdatedAt
			}
			r.ArtifactDigest = digest
			r.LastComplete = &ReviewCompletion{Verdict: r.Verdict, Artifact: r.Path, ArtifactDigest: digest, InputFingerprint: r.Fingerprint, CompletedAt: completedAt}
		}
	}
	if state.Smoke != nil {
		sm := state.Smoke
		sm.Stale = true
		if sm.Status == SmokeCompleted {
			digest, _ := hashFile(mustArtifactPath(root, sp, StageSmoke))
			if digest == "" {
				digest = "legacy-unverifiable"
			}
			completedAt := derefTime(sm.LastRunAt)
			if completedAt.IsZero() {
				completedAt = state.UpdatedAt
			}
			sm.ArtifactDigest = digest
			sm.InputFingerprint = "legacy-unverifiable"
			sm.LastComplete = &SmokeCompletion{Verdict: sm.Verdict, Artifact: sm.Path, ArtifactDigest: digest, InputFingerprint: sm.InputFingerprint, CompletedAt: completedAt, RunID: sm.RunID, EvidenceID: sm.EvidenceID}
		}
	}
	return state
}

func derefTime(value *time.Time) time.Time {
	if value == nil {
		return time.Time{}
	}
	return value.UTC()
}

func SaveFlowState(root string, s Sprint, state FlowState) error {
	// Planning-stage refreshes must not erase the last complete verification
	// evidence. Explicit stage writers load and replace their own record.
	if state.Review == nil || state.Smoke == nil || state.QA == nil || state.Repair == nil || state.Performance == nil {
		if prior, err := LoadFlowState(root, s); err == nil {
			if state.Review == nil {
				state.Review = prior.Review
			}
			if state.Smoke == nil {
				state.Smoke = prior.Smoke
			}
			if state.QA == nil {
				state.QA = prior.QA
			}
			if state.Repair == nil {
				state.Repair = prior.Repair
			}
			if state.Performance == nil {
				state.Performance = prior.Performance
			}
		} else if !errors.Is(err, ErrFlowStateMissing) {
			return err
		}
	}
	if authoritative, err := FlowStateInDatabase(root, s); err != nil {
		return err
	} else if authoritative {
		if err := saveFlowStateDatabase(root, s, state); err != nil {
			return err
		}
		if !flowStateCheckpoint(state) {
			return nil
		}
		return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
	}
	return saveFlowStateWithHooks(root, s, state, atomicWriteHooks{})
}

func flowStateCheckpoint(state FlowState) bool {
	for _, stage := range state.Stages {
		if stage.Status != StatusComplete && stage.Status != StatusFailed && stage.Status != StatusSkipped {
			return false
		}
	}
	return len(state.Stages) > 0
}

func saveFlowStateWithHooks(root string, s Sprint, state FlowState, hooks atomicWriteHooks) error {
	path, err := FlowStatePath(root, s)
	if err != nil {
		return err
	}
	state.UpdatedAt = time.Now().UTC()
	if err := ValidateFlowState(root, s, state, path); err != nil {
		return err
	}
	content, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal flow state %s: %w", path, err)
	}
	content = append(content, '\n')
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create flow state directory %s: %w", filepath.Dir(path), err)
	}
	temp, err := os.CreateTemp(filepath.Dir(path), ".flow-state.*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary flow state %s: %w", path, err)
	}
	tempPath := temp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tempPath)
		}
	}()
	if _, err := temp.Write(content); err != nil {
		_ = temp.Close()
		return fmt.Errorf("write temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Sync(); err != nil {
		_ = temp.Close()
		return fmt.Errorf("flush temporary flow state %s: %w", tempPath, err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("close temporary flow state %s: %w", tempPath, err)
	}
	if hooks.BeforeRename != nil {
		if err := hooks.BeforeRename(path); err != nil {
			return fmt.Errorf("prepare flow state rename %s: %w", path, err)
		}
	}
	if err := os.Rename(tempPath, path); err != nil {
		return fmt.Errorf("rename flow state %s: %w", path, err)
	}
	cleanup = false
	syncDir(filepath.Dir(path))
	return nil
}

func ValidateFlowState(root string, s Sprint, state FlowState, path string) error {
	if state.SchemaVersion == 0 {
		return fmt.Errorf("%w: %s: missing schemaVersion", ErrFlowStateMalformed, path)
	}
	if state.SchemaVersion != FlowStateSchemaVersion {
		return fmt.Errorf("%w: %s: schemaVersion %d", ErrFlowStateUnsupported, path, state.SchemaVersion)
	}
	if state.Project == "" || state.Sprint == "" || state.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: %s: missing required top-level fields", ErrFlowStateMalformed, path)
	}
	if state.Project != s.Project {
		return fmt.Errorf("%w: %s: project mismatch %q", ErrFlowStateMalformed, path, state.Project)
	}
	if state.Sprint != s.Slug {
		return fmt.Errorf("%w: %s: sprint mismatch %q", ErrFlowStateMalformed, path, state.Sprint)
	}
	if len(state.Stages) != len(PlanningStages()) {
		return fmt.Errorf("%w: %s: expected %d stages", ErrFlowStateMalformed, path, len(PlanningStages()))
	}
	seen := map[PlanningStage]bool{}
	for i, stage := range state.Stages {
		if stage.Stage != PlanningStages()[i] {
			return fmt.Errorf("%w: %s: stage %d is %q; expected %q", ErrFlowStateMalformed, path, i, stage.Stage, PlanningStages()[i])
		}
		if !ValidStage(stage.Stage) {
			return fmt.Errorf("%w: %s: unsupported stage %q", ErrFlowStateMalformed, path, stage.Stage)
		}
		if seen[stage.Stage] {
			return fmt.Errorf("%w: %s: duplicate stage %q", ErrFlowStateMalformed, path, stage.Stage)
		}
		seen[stage.Stage] = true
		if !ValidStatus(stage.Status) {
			return fmt.Errorf("%w: %s: stage %q has unsupported status %q", ErrFlowStateMalformed, path, stage.Stage, stage.Status)
		}
		if stage.Path == "" {
			return fmt.Errorf("%w: %s: stage %d missing path", ErrFlowStateMalformed, path, i)
		}
		if filepath.IsAbs(stage.Path) || strings.HasPrefix(filepath.ToSlash(filepath.Clean(filepath.FromSlash(stage.Path))), "../") {
			return fmt.Errorf("%w: %s: stage %q has unsafe path", ErrFlowStateMalformed, path, stage.Stage)
		}
		if _, err := resolveSprintContained(root, s, stage.Path); err != nil {
			return fmt.Errorf("%w: %s: stage %q has unsafe path: %w", ErrFlowStateMalformed, path, stage.Stage, err)
		}
		if strings.ContainsAny(stage.Error, "\x00\r\n") {
			return fmt.Errorf("%w: %s: stage %q has unsafe error detail", ErrFlowStateMalformed, path, stage.Stage)
		}
		switch stage.LatestOutcome {
		case "", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		default:
			return fmt.Errorf("%w: %s: stage %q has unsupported latest outcome %q", ErrFlowStateMalformed, path, stage.Stage, stage.LatestOutcome)
		}
	}
	for _, expected := range PlanningStages() {
		if !seen[expected] {
			return fmt.Errorf("%w: %s: missing stage %q", ErrFlowStateMalformed, path, expected)
		}
	}
	if state.Review != nil {
		if err := validateReviewStageState(root, s, *state.Review, path); err != nil {
			return err
		}
	}
	if state.Smoke != nil {
		if err := validateSmokeStageState(root, s, *state.Smoke, path); err != nil {
			return err
		}
	}
	if state.QA != nil {
		if err := validateQAFlowSummary(root, s, *state.QA, path); err != nil {
			return err
		}
	}
	if state.Repair != nil {
		if err := validateRepairFlowSummary(root, s, *state.Repair, path); err != nil {
			return err
		}
	}
	if state.Performance != nil {
		if err := validatePerformanceFlowSummary(root, s, *state.Performance, path); err != nil {
			return err
		}
	}
	return nil
}

func validatePerformanceFlowSummary(root string, s Sprint, summary PerformanceFlowSummary, path string) error {
	switch summary.Phase {
	case PerformancePhaseReady, PerformancePhasePreparing, PerformancePhaseBaseline, PerformancePhaseOptimizing, PerformancePhaseFinalizing, PerformancePhaseTerminal, PerformancePhaseStale:
	default:
		return fmt.Errorf("%w: %s: invalid performance phase", ErrFlowStateMalformed, path)
	}
	if summary.Required < 0 || summary.Reports < 0 || summary.Met < 0 || summary.Missed < 0 || summary.Met+summary.Missed > summary.Required+summary.Reports {
		return fmt.Errorf("%w: %s: invalid performance counts", ErrFlowStateMalformed, path)
	}
	if summary.StatePath == "" || !validFingerprint(summary.StateDigest) || strings.TrimSpace(summary.NextAction) == "" {
		return fmt.Errorf("%w: %s: incomplete performance summary pointer", ErrFlowStateMalformed, path)
	}
	resolved, err := resolveSprintContained(root, s, summary.StatePath)
	if err != nil || filepath.Base(resolved) != "performance-state.json" || filepath.Base(filepath.Dir(resolved)) != "verification" {
		return fmt.Errorf("%w: %s: unsafe performance summary pointer", ErrFlowStateMalformed, path)
	}
	return nil
}

func validateRepairFlowSummary(root string, s Sprint, summary RepairFlowSummary, path string) error {
	if !validRepairPhase(summary.Phase) || !validRepairMode(summary.Mode) || !validRepairID(summary.RepairRunID, "run") || !validQAIDKind(summary.QAAttemptID, "attempt") || summary.CurrentCycle < 0 || strings.TrimSpace(summary.NextAction) == "" {
		return fmt.Errorf("%w: %s: invalid repair summary", ErrFlowStateMalformed, path)
	}
	if summary.Outcome != "" && !validRepairOutcome(summary.Outcome) {
		return fmt.Errorf("%w: %s: invalid repair summary outcome", ErrFlowStateMalformed, path)
	}
	if summary.StatePath == "" || !validFingerprint(summary.StateDigest) {
		return fmt.Errorf("%w: %s: incomplete repair summary pointer", ErrFlowStateMalformed, path)
	}
	resolved, err := resolveSprintContained(root, s, summary.StatePath)
	if err != nil || filepath.Base(resolved) != "repair-state.json" || filepath.Base(filepath.Dir(resolved)) != "verification" {
		return fmt.Errorf("%w: %s: unsafe repair summary pointer", ErrFlowStateMalformed, path)
	}
	return nil
}

func validateQAFlowSummary(root string, s Sprint, summary QAFlowSummary, path string) error {
	if !containsQAPhase(summary.Phase) || summary.CompletedShards < 0 || summary.TotalShards < 0 || summary.CompletedShards > summary.TotalShards || summary.Confirmed < 0 || summary.Blocked < 0 {
		return fmt.Errorf("%w: %s: invalid QA summary", ErrFlowStateMalformed, path)
	}
	if summary.StatePath == "" || !validFingerprint(summary.StateDigest) || strings.TrimSpace(summary.NextAction) == "" {
		return fmt.Errorf("%w: %s: incomplete QA summary pointer", ErrFlowStateMalformed, path)
	}
	resolved, err := resolveSprintContained(root, s, summary.StatePath)
	if err != nil || filepath.Base(resolved) != "state.json" || filepath.Base(filepath.Dir(resolved)) != "verification" {
		return fmt.Errorf("%w: %s: unsafe QA summary pointer", ErrFlowStateMalformed, path)
	}
	if summary.CurrentAttemptID != "" && !validQAID(summary.CurrentAttemptID) {
		return fmt.Errorf("%w: %s: invalid QA summary attempt ID", ErrFlowStateMalformed, path)
	}
	return nil
}

func NewFlowState(s Sprint, stages []StageState, now time.Time) FlowState {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	return FlowState{
		SchemaVersion: FlowStateSchemaVersion,
		Project:       s.Project,
		Sprint:        s.Slug,
		UpdatedAt:     now.UTC(),
		Stages:        stages,
	}
}

func syncDir(path string) {
	dir, err := os.Open(path)
	if err != nil {
		return
	}
	defer dir.Close()
	_ = dir.Sync()
}

